        ) {
            this.assetId = assetId;
            this.cover256Path = cover256Path;
            this.cover1024Path = cover1024Path;
            this.vibrantColors = vibrantColors;
            this.representativeColors = representativeColors;
        }

        JSObject toJSObject() {
