import React, { useCallback, useEffect, useMemo, useState } from 'react';
import type { MotionValue } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import { useShallow } from 'zustand/react/shallow';
import {
    type LocalPlaylist,
    type LocalSong,
    type LyricData,
    PlayerState,
    type ReplayGainMode,
    type SongResult,
    type Theme,
} from '../../types';
import { type LocalLibraryDisplayCatalog, buildLocalQueue } from '../../services/playbackAdapters';
import {
    LOCAL_MUSIC_SCAN_PROGRESS_EVENT,
    type LocalMusicScanProgressDetail,
    cancelLocalLibraryScan,
    getActiveLocalMusicScanProgress,
    importFolder,
    resyncAllFolders,
} from '../../services/localMusicService';
import { importLocalPlaylistFile } from '../../services/localPlaylistFileService';
import { getSongAlbumLabel, getSongArtistLabel } from '../../services/onlineMusic/songMetadata';
import { usePlaybackStore } from '../../stores/usePlaybackStore';
import { closeSettings, openSettings, useSettingsModalStore } from '../../stores/useSettingsModalStore';
import { setStatusMessage } from '../../stores/useStatusMessageStore';
import { useThemeSettingsStore } from '../../stores/useThemeSettingsStore';
import { useTypographySettingsStore } from '../../stores/useTypographySettingsStore';
import type { NavidromeSong } from '../../types/navidrome';
import { useAudioSettingsStore } from '../../stores/useAudioSettingsStore';
import { useVisualizerSettingsStore } from '../../stores/useVisualizerSettingsStore';
import { closeLoginWindow, useLoginWindowStore } from '../login/loginWindowStore';
import MobilePlayerShell from './MobilePlayerShell';

// src/components/mobile/MobileAppContainer.tsx
// Connects the Phase 4 MobilePlayerShell to Folia's stores and local music services.

interface MobileAppContainerProps {
    localSongs: LocalSong[];
    localPlaylists: LocalPlaylist[];
    localLibraryCatalog: LocalLibraryDisplayCatalog;
    currentSong: SongResult | null;
    coverUrl: string | null;
    playerState: PlayerState;
    currentTime: MotionValue<number>;
    lyricCurrentTime: MotionValue<number>;
    duration: number;
    lyrics: LyricData | null;
    currentLineIndex: number;
    isLyricsLoading: boolean;
    isLiked: boolean;
    loopMode: 'off' | 'all' | 'one';
    replayGainMode: ReplayGainMode;
    onChangeReplayGainMode: (mode: ReplayGainMode) => void;
    theme: Theme;
    onToggleDaylight: () => void;
    lyricTimelineOffsetMs: number;
    onLyricTimelineOffsetChange: (offsetMs: number) => void;
    onChangeLyricsSource: (source: 'local' | 'embedded' | 'online') => void;
    onUpdateLocalLyrics: (content: string, isTranslation: boolean, fileName?: string) => void;
    onOpenLyricMatch: () => void;
    onCloseLyricMatch: () => void;
    isLyricMatchOpen: boolean;
    onTogglePureMusic?: () => void;
    onRefreshLocalSongs: () => Promise<void> | void;
    onPlayLocalSong: (song: LocalSong, queue?: LocalSong[]) => Promise<void> | void;
    onAddLocalSongToQueue: (song: LocalSong) => void;
    playQueue: SongResult[];
    onPlayQueueSong: (song: SongResult, queue: SongResult[]) => void;
    onRemoveQueueSong: (index: number) => void;
    onSaveQueueAsPlaylist: (name: string) => Promise<void>;
    onSeek: (timeSec: number) => void;
    onLyricLineSeek: (timeSec: number) => void;
    onTogglePlay: () => void;
    onPrevTrack: () => void;
    onNextTrack: () => void;
    onToggleLoop: () => void;
    onToggleLike: () => void;
    onShuffleQueue: () => void;
    isCommandPaletteOpen: boolean;
    onCloseCommandPalette: () => void;
    onVisualizerVisibilityChange?: (visible: boolean) => void;
    isLatticeOpen?: boolean;
    onOpenLattice?: () => void;
    onCloseLattice?: () => void;
    onPlayOnlineSong?: (song: SongResult, queue?: SongResult[]) => void;
    onAddOnlineSongToQueue?: (song: SongResult) => void;
    onPlayNavidromeSong?: (song: NavidromeSong, queue?: NavidromeSong[]) => void;
    onAddNavidromeSongsToQueue?: (songs: NavidromeSong[]) => void;
    onOpenFullSearchWorkspace?: () => void;
    onCloseSearch?: () => void;
    isSearchOpen?: boolean;
    onAutoMatchLyrics?: () => void;
}

export const MobileAppContainer: React.FC<MobileAppContainerProps> = ({
    localSongs,
    localPlaylists,
    localLibraryCatalog,
    currentSong,
    coverUrl,
    playerState,
    currentTime,
    lyricCurrentTime,
    duration,
    lyrics,
    currentLineIndex,
    isLyricsLoading,
    isLiked,
    loopMode,
    replayGainMode,
    onChangeReplayGainMode,
    theme,
    onToggleDaylight,
    lyricTimelineOffsetMs,
    onLyricTimelineOffsetChange,
    onChangeLyricsSource,
    onUpdateLocalLyrics,
    onOpenLyricMatch,
    onCloseLyricMatch,
    isLyricMatchOpen,
    onTogglePureMusic,
    onRefreshLocalSongs,
    onPlayLocalSong,
    onAddLocalSongToQueue,
    playQueue,
    onPlayQueueSong,
    onRemoveQueueSong,
    onSaveQueueAsPlaylist,
    onSeek,
    onLyricLineSeek,
    onTogglePlay,
    onPrevTrack,
    onNextTrack,
    onToggleLoop,
    onToggleLike,
    onShuffleQueue,
    isCommandPaletteOpen,
    onCloseCommandPalette,
    onVisualizerVisibilityChange,
    isLatticeOpen = false,
    onOpenLattice,
    onCloseLattice,
    onPlayOnlineSong,
    onAddOnlineSongToQueue,
    onPlayNavidromeSong,
    onAddNavidromeSongsToQueue,
    onOpenFullSearchWorkspace,
    onCloseSearch,
    isSearchOpen = false,
    onAutoMatchLyrics,
}) => {
    const isEqualizerOpen = useAudioSettingsStore(state => state.isAudioEqualizerOpen);
    const closeEqualizer = useAudioSettingsStore(state => state.closeAudioEqualizer);
    const isLoginWindowOpen = useLoginWindowStore(state => state.isOpen);
    const { t } = useTranslation();
    const activeLocalLyricsSource = usePlaybackStore(state => state.activeLocalLyricsSource);
    const isSettingsModalOpen = useSettingsModalStore(state => state.settingsModalState.isOpen);
    const { isDaylight, useCoverColorBg, handleToggleCoverColorBg } = useThemeSettingsStore(
        useShallow(state => ({
            isDaylight: state.isDaylight,
            useCoverColorBg: state.useCoverColorBg,
            handleToggleCoverColorBg: state.handleToggleCoverColorBg,
        })),
    );
    const { visualizerMode, handleSetVisualizerMode } = useVisualizerSettingsStore(
        useShallow(state => ({
            visualizerMode: state.visualizerMode,
            handleSetVisualizerMode: state.handleSetVisualizerMode,
        })),
    );
    const {
        lyricsFontScale,
        handleSetLyricsFontScale,
        showSubtitleTranslation,
        handleToggleSubtitleTranslation,
    } = useTypographySettingsStore(
        useShallow(state => ({
            lyricsFontScale: state.lyricsFontScale,
            handleSetLyricsFontScale: state.handleSetLyricsFontScale,
            showSubtitleTranslation: state.showSubtitleTranslation,
            handleToggleSubtitleTranslation: state.handleToggleShowSubtitleTranslation,
        })),
    );

    const [isBusy, setIsBusy] = useState(false);
    const [scanProgress, setScanProgress] = useState<LocalMusicScanProgressDetail | null>(() => getActiveLocalMusicScanProgress());
    const scanPercent = useMemo(() => {
        if (!scanProgress?.active) return 0;
        if (!scanProgress.totalSongs || scanProgress.totalSongs <= 0) return 5;
        return Math.min(100, Math.round(((scanProgress.completedSongs ?? 0) / scanProgress.totalSongs) * 100));
    }, [scanProgress]);

    useEffect(() => {
        if (typeof window === 'undefined') return undefined;
        const onScanProgress = (event: Event) => {
            const detail = (event as CustomEvent<LocalMusicScanProgressDetail>).detail;
            setScanProgress(detail ? { ...detail } : null);
        };
        window.addEventListener(LOCAL_MUSIC_SCAN_PROGRESS_EVENT, onScanProgress);
        return () => window.removeEventListener(LOCAL_MUSIC_SCAN_PROGRESS_EVENT, onScanProgress);
    }, []);

    const handleCancelScan = useCallback(() => {
        cancelLocalLibraryScan(scanProgress?.folderName);
    }, [scanProgress?.folderName]);

    const handleImportFolder = useCallback(async () => {
        if (isBusy) return;
        setIsBusy(true);
        try {
            const imported = await importFolder();
            if (imported.length > 0) {
                await onRefreshLocalSongs();
                setStatusMessage({
                    type: 'success',
                    text: `Imported ${imported.length} tracks`,
                });
            }
        } catch (error) {
            console.error('[MobileAppContainer] Failed to import folder:', error);
            setStatusMessage({
                type: 'error',
                text: t('localMusic.importNotSupported', 'Failed to import folder'),
            });
        } finally {
            setIsBusy(false);
        }
    }, [isBusy, onRefreshLocalSongs, t]);

    const handleRefreshFolders = useCallback(async () => {
        if (isBusy) return;
        setIsBusy(true);
        try {
            const resynced = await resyncAllFolders();
            if ((resynced?.length ?? 0) > 0) {
                await onRefreshLocalSongs();
            }
        } catch (error) {
            console.error('[MobileAppContainer] Failed to resync folders:', error);
        } finally {
            setIsBusy(false);
        }
    }, [isBusy, onRefreshLocalSongs]);

    const handleImportPlaylist = useCallback(async (file: File) => {
        if (isBusy) return;
        setIsBusy(true);
        try {
            const result = await importLocalPlaylistFile(file, localSongs);
            if (result.playlist?.name) {
                await onRefreshLocalSongs();
                setStatusMessage({
                    type: 'success',
                    text: `Imported playlist "${result.playlist.name}" (${result.matchedSongIds.length} tracks)`,
                });
            } else {
                setStatusMessage({
                    type: 'error',
                    text: t('localMusic.playlistImportNoMatches', 'No matching tracks found in library'),
                });
            }
        } catch (error) {
            console.error('[MobileAppContainer] Failed to import playlist file:', error);
        } finally {
            setIsBusy(false);
        }
    }, [isBusy, localSongs, onRefreshLocalSongs, t]);

    const artistName = useMemo(
        () => (currentSong ? getSongArtistLabel(currentSong) || t('localMusic.unknownArtist', 'Unknown Artist') : ''),
        [currentSong, t],
    );
    const albumName = useMemo(
        () => (currentSong ? getSongAlbumLabel(currentSong) || '' : ''),
        [currentSong],
    );

    const externalModals = useMemo(() => ({
        isLyricMatchOpen,
        isSettingsModalOpen,
        isCommandPaletteOpen,
        isEqualizerOpen,
        isSearchOpen,
        isLoginWindowOpen,
        closeLyricMatch: onCloseLyricMatch,
        closeSettingsModal: closeSettings,
        closeCommandPalette: onCloseCommandPalette,
        closeEqualizer,
        closeSearch: onCloseSearch,
        closeLoginWindow,
    }), [
        closeEqualizer,
        isCommandPaletteOpen,
        isEqualizerOpen,
        isLoginWindowOpen,
        isLyricMatchOpen,
        isSearchOpen,
        isSettingsModalOpen,
        onCloseCommandPalette,
        onCloseLyricMatch,
        onCloseSearch,
    ]);

    return (
        <MobilePlayerShell
            localSongs={localSongs}
            localPlaylists={localPlaylists}
            localLibraryCatalog={localLibraryCatalog}
            currentSong={currentSong}
            artistName={artistName}
            albumName={albumName}
            coverUrl={coverUrl}
            playerState={playerState}
            currentTime={currentTime}
            lyricCurrentTime={lyricCurrentTime}
            duration={duration}
            lyrics={lyrics}
            currentLineIndex={currentLineIndex}
            isLyricsLoading={isLyricsLoading}
            isLiked={isLiked}
            loopMode={loopMode}
            replayGainMode={replayGainMode}
            onChangeReplayGainMode={onChangeReplayGainMode}
            theme={theme}
            isDaylight={isDaylight}
            onToggleDaylight={onToggleDaylight}
            useCoverColorBg={useCoverColorBg}
            onToggleCoverColorBg={handleToggleCoverColorBg}
            visualizerMode={visualizerMode}
            onVisualizerModeChange={handleSetVisualizerMode}
            lyricsFontScale={lyricsFontScale}
            onLyricsFontScaleChange={handleSetLyricsFontScale}
            showSubtitleTranslation={showSubtitleTranslation}
            onToggleSubtitleTranslation={handleToggleSubtitleTranslation}
            lyricTimelineOffsetMs={lyricTimelineOffsetMs}
            onLyricTimelineOffsetChange={onLyricTimelineOffsetChange}
            activeLocalLyricsSource={activeLocalLyricsSource}
            onChangeLyricsSource={onChangeLyricsSource}
            onImportLocalLyricsFile={(content, fileName) => onUpdateLocalLyrics(content, false, fileName)}
            onOpenLyricMatch={onOpenLyricMatch}
            onAutoMatchLyrics={onAutoMatchLyrics}
            onTogglePureMusic={onTogglePureMusic}
            onImportFolder={handleImportFolder}
            onRefreshFolders={handleRefreshFolders}
            onImportPlaylistFile={handleImportPlaylist}
            isImportingOrScanning={isBusy || Boolean(scanProgress?.active)}
            scanPercent={scanPercent}
            scanProgress={scanProgress}
            onCancelScan={handleCancelScan}
            onPlayLocalSongList={(song, queue) => {
                void onPlayLocalSong(song, queue);
            }}
            onAddLocalSongToQueue={onAddLocalSongToQueue}
            onPlayQueueSong={onPlayQueueSong}
            playQueue={playQueue}
            onRemoveQueueSong={onRemoveQueueSong}
            onSaveQueueAsPlaylist={onSaveQueueAsPlaylist}
            onSeek={onSeek}
            onLyricLineSeek={onLyricLineSeek}
            onTogglePlay={onTogglePlay}
            onPrevTrack={onPrevTrack}
            onNextTrack={onNextTrack}
            onToggleLoop={onToggleLoop}
            onToggleLike={onToggleLike}
            onShuffleQueue={onShuffleQueue}
            onOpenFullSettingsModal={() => openSettings('options')}
            externalModals={externalModals}
            onVisualizerVisibilityChange={onVisualizerVisibilityChange}
            isLatticeOpen={isLatticeOpen}
            onOpenLattice={onOpenLattice}
            onCloseLattice={onCloseLattice}
            onPlayOnlineSong={onPlayOnlineSong}
            onAddOnlineSongToQueue={onAddOnlineSongToQueue}
            onPlayNavidromeSong={onPlayNavidromeSong}
            onAddNavidromeSongsToQueue={onAddNavidromeSongsToQueue}
            onOpenFullSearchWorkspace={onOpenFullSearchWorkspace}
        />
    );
};

export default React.memo(MobileAppContainer);
export { buildLocalQueue };

src/components/mobile/MobileEqualizerShe:
import React, { useEffect, useMemo, useState } from 'react';
import {
    Activity,
    AlertTriangle,
    CheckCircle2,
    RotateCcw,
    Sliders,
    Sparkles,
    X,
} from 'lucide-react';
import {
    AUDIO_EQUALIZER_BANDS,
    AUDIO_EQUALIZER_CUSTOM_SLOT_IDS,
    AUDIO_EQUALIZER_MAX_GAIN_DB,
    AUDIO_EQUALIZER_MIN_GAIN_DB,
    AUDIO_EQUALIZER_PRESET_LABELS,
    getAudioEqualizerCustomSlotIndex,
    isAudioEqualizerCustomSlotId,
    isAudioEqualizerFlat,
    resetAudioEqualizerToFlat,
    type AudioEqualizerCustomSlotId,
    type AudioEqualizerModeId,
    type AudioEqualizerSettings,
} from '../../utils/audioEqualizer';
import { AUDIO_SOUND_PRESETS, AUDIO_SOUND_PRESET_IDS } from '../../utils/audioPresets';
import {
    createNeutralAudioEffects,
    type AudioEffectId,
    type AudioEffectSettings,
} from '../../utils/audioEffects';
import {
    computeEqualizerFrequencyResponseDb,
    getAudioEqualizerRuntimeStatus,
    subscribeAudioEqualizerRuntime,
} from '../../services/audioEqualizerGraph';
import { useAudioSettingsStore } from '../../stores/useAudioSettingsStore';

// src/components/mobile/MobileEqualizerSheet.tsx
// Mobile-first 10-band Audio Equalizer & Effects panel connected directly to the live
// Web Audio BiquadFilterNode playback chain via useAudioSettingsStore.

interface MobileEqualizerSheetProps {
    accentColor: string;
    onClose: () => void;
    onOpenFullDesktopEqualizer?: () => void;
}

const ALL_PRESET_IDS: readonly AudioEqualizerModeId[] = [
    ...AUDIO_SOUND_PRESET_IDS,
    ...AUDIO_EQUALIZER_CUSTOM_SLOT_IDS,
];

const formatSignedDb = (val: number): string => {
    const rounded = Math.round(val * 10) / 10;
    if (rounded > 0) return `+${rounded} dB`;
    if (rounded < 0) return `${rounded} dB`;
    return '0 dB';
};

const formatFrequencyLabel = (hz: number): string => (
    hz >= 1000 ? `${hz / 1000} kHz` : `${hz} Hz`
);

export const MobileEqualizerSheet: React.FC<MobileEqualizerSheetProps> = ({
    accentColor,
    onClose,
    onOpenFullDesktopEqualizer,
}) => {
    const settings = useAudioSettingsStore(state => state.audioEqualizerSettings);
    const setSettings = useAudioSettingsStore(state => state.handleSetAudioEqualizerSettings);
    const applyPresetInStore = useAudioSettingsStore(state => state.handleApplyAudioSoundPreset);
    const [showEffects, setShowEffects] = useState(false);
    const [runtimeStatus, setRuntimeStatus] = useState(() => getAudioEqualizerRuntimeStatus());

    useEffect(() => {
        setRuntimeStatus(getAudioEqualizerRuntimeStatus());
        return subscribeAudioEqualizerRuntime(() => {
            setRuntimeStatus(getAudioEqualizerRuntimeStatus());
        });
    }, [settings]);

    const responseCurveDb = useMemo(
        () => computeEqualizerFrequencyResponseDb(settings, AUDIO_EQUALIZER_BANDS.map(b => b.frequency), runtimeStatus.sampleRate ?? 48_000),
        [runtimeStatus.sampleRate, settings],
    );

    const svgPath = useMemo(() => {
        const points = AUDIO_EQUALIZER_BANDS.map((_, index) => {
            const x = (index / (AUDIO_EQUALIZER_BANDS.length - 1)) * 100;
            const gain = settings.enabled ? (settings.gains[index] ?? 0) : 0;
            const normalized = (AUDIO_EQUALIZER_MAX_GAIN_DB - gain) / (AUDIO_EQUALIZER_MAX_GAIN_DB - AUDIO_EQUALIZER_MIN_GAIN_DB);
            const y = Math.max(4, Math.min(96, normalized * 100));
            return [x, y] as const;
        });
        return points.slice(1).reduce((acc, [x, y], idx) => {
            const [prevX, prevY] = points[idx]!;
            const midX = (prevX + x) / 2;
            return `${acc} C ${midX.toFixed(1)},${prevY.toFixed(1)} ${midX.toFixed(1)},${y.toFixed(1)} ${x.toFixed(1)},${y.toFixed(1)}`;
        }, `M ${points[0]![0].toFixed(1)},${points[0]![1].toFixed(1)}`);
    }, [settings.enabled, settings.gains]);

    const handleToggleEnabled = () => {
        setSettings({
            ...settings,
            enabled: !settings.enabled,
        });
    };

    const handleSelectPreset = (presetId: AudioEqualizerModeId) => {
        applyPresetInStore(presetId);
    };

    const writeCustomBandOrEffect = (nextGains: number[], nextEffects: AudioEffectSettings) => {
        const slotId: AudioEqualizerCustomSlotId = isAudioEqualizerCustomSlotId(settings.preset)
            ? settings.preset
            : AUDIO_EQUALIZER_CUSTOM_SLOT_IDS[0];
        const slotIndex = getAudioEqualizerCustomSlotIndex(slotId);
        const next: AudioEqualizerSettings = {
            ...settings,
            enabled: true,
            preset: slotId,
            gains: nextGains,
            effects: nextEffects,
            customSlots: settings.customSlots.map((slot, index) => (
                index === slotIndex ? { gains: [...nextGains], effects: { ...nextEffects } } : slot
            )),
        };
        setSettings(next);
    };

    const handleBandChange = (bandIndex: number, gainDb: number) => {
        const nextGains = [...settings.gains];
        nextGains[bandIndex] = gainDb;
        writeCustomBandOrEffect(nextGains, { ...settings.effects });
    };

    const handleEffectChange = (effectId: AudioEffectId, value: number) => {
        writeCustomBandOrEffect([...settings.gains], {
            ...settings.effects,
            [effectId]: value,
        });
    };

    const handleResetToFlat = () => {
        setSettings(resetAudioEqualizerToFlat(settings));
    };

    const handleResetEffectsOnly = () => {
        writeCustomBandOrEffect([...settings.gains], createNeutralAudioEffects());
    };

    const canReset = !isAudioEqualizerFlat(settings) || isAudioEqualizerCustomSlotId(settings.preset);

    return (
        <div
            data-testid="mobile-equalizer-sheet"
            className="flex flex-col max-h-[84dvh] overflow-hidden rounded-t-3xl border-t border-white/15 bg-[#0b0b11]/98 text-zinc-100 shadow-2xl backdrop-blur-2xl"
            style={{ paddingBottom: 'max(env(safe-area-inset-bottom, 0px), 16px)' }}
        >
            {/* Header Bar */}
            <div className="flex items-center justify-between gap-3 border-b border-white/10 px-5 py-3.5">
                <div className="flex items-center gap-2.5 min-w-0">
                    <div
                        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border border-white/15 bg-white/[0.06]"
                        style={{ color: settings.enabled ? accentColor : '#a1a1aa' }}
                    >
                        <Sliders size={18} />
                    </div>
                    <div className="min-w-0">
                        <h3 className="truncate text-base font-bold text-white">Audio Equalizer & Effects</h3>
                        <p className="truncate text-[11px] text-zinc-400">
                            10-Band Parametric/Shelf EQ ({AUDIO_EQUALIZER_MIN_GAIN_DB} dB to +{AUDIO_EQUALIZER_MAX_GAIN_DB} dB)
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-2 shrink-0">
                    {/* On/Off Toggle Pill */}
                    <button
                        type="button"
                        role="switch"
                        aria-checked={settings.enabled}
                        data-testid="mobile-equalizer-toggle"
                        onClick={handleToggleEnabled}
                        className={`flex h-9 items-center gap-2 rounded-full border px-3.5 text-xs font-semibold transition-all active:scale-95 ${
                            settings.enabled
                                ? 'border-white/30 bg-white text-zinc-950 shadow-sm'
                                : 'border-white/15 bg-white/[0.06] text-zinc-300'
                        }`}
                    >
                        <span
                            className={`h-2 w-2 rounded-full ${
                                settings.enabled ? 'bg-emerald-500' : 'bg-zinc-500'
                            }`}
                        />
                        <span>{settings.enabled ? 'On' : 'Off'}</span>
                    </button>

                    <button
                        type="button"
                        onClick={onClose}
                        className="flex h-9 w-9 items-center justify-center rounded-full bg-white/10 text-zinc-300 active:scale-95"
                        aria-label="Close equalizer"
                    >
                        <X size={18} />
                    </button>
                </div>
            </div>

            {/* Scrollable Body */}
            <div className="flex-1 overflow-y-auto overscroll-contain px-5 py-4 space-y-4">
                {/* Real-Time Audio Engine Status Banner */}
                <div
                    data-testid="mobile-equalizer-engine-status"
                    className={`flex items-center justify-between gap-2.5 rounded-2xl border px-3.5 py-2.5 text-xs ${
                        !runtimeStatus.supported
                            ? 'border-amber-400/30 bg-amber-500/10 text-amber-200'
                            : runtimeStatus.connected
                                ? 'border-emerald-400/25 bg-emerald-500/10 text-emerald-200'
                                : 'border-white/10 bg-white/[0.04] text-zinc-300'
                    }`}
                >
                    <div className="flex items-center gap-2 min-w-0">
                        {!runtimeStatus.supported ? (
                            <AlertTriangle size={15} className="shrink-0 text-amber-400" />
                        ) : runtimeStatus.connected ? (
                            <CheckCircle2 size={15} className="shrink-0 text-emerald-400" />
                        ) : (
                            <Activity size={15} className="shrink-0 text-zinc-400" />
                        )}
                        <span className="truncate font-medium">
                            {!runtimeStatus.supported
                                ? (runtimeStatus.reason || 'Audio effects unsupported in this environment')
                                : runtimeStatus.connected
                                    ? `Live Web Audio 10-Band Biquad DSP Active${runtimeStatus.sampleRate ? ` (${Math.round(runtimeStatus.sampleRate / 100) / 10} kHz)` : ''}`
                                    : 'Web Audio 10-Band Biquad DSP Ready — engages automatically on playback'}
                        </span>
                    </div>
                    {onOpenFullDesktopEqualizer && (
                        <button
                            type="button"
                            onClick={onOpenFullDesktopEqualizer}
                            className="shrink-0 rounded-lg border border-white/15 bg-white/10 px-2.5 py-1 text-[11px] font-semibold text-white"
                        >
                            Studio View
                        </button>
                    )}
                </div>

                {/* Preset Chips + Reset to Flat */}
                <div className="space-y-2">
                    <div className="flex items-center justify-between">
                        <span className="text-xs font-semibold uppercase tracking-wider text-zinc-400">
                            Sound Presets
                        </span>
                        <button
                            type="button"
                            data-testid="mobile-equalizer-reset-flat"
                            disabled={!canReset}
                            onClick={handleResetToFlat}
                            className="flex items-center gap-1.5 rounded-full border border-white/15 bg-white/[0.06] px-3 py-1 text-xs font-semibold text-zinc-200 disabled:opacity-40 active:scale-95 transition-all"
                        >
                            <RotateCcw size={12} />
                            <span>Reset to Flat</span>
                        </button>
                    </div>

                    <div className="flex flex-wrap gap-1.5">
                        {ALL_PRESET_IDS.map((presetId) => {
                            const active = settings.preset === presetId;
                            return (
                                <button
                                    key={presetId}
                                    type="button"
                                    data-testid={`eq-preset-${presetId}`}
                                    onClick={() => handleSelectPreset(presetId)}
                                    className={`rounded-xl border px-3 py-1.5 text-xs font-semibold transition-all active:scale-95 ${
                                        active
                                            ? 'border-white bg-white text-zinc-950 shadow-sm'
                                            : 'border-white/10 bg-white/[0.04] text-zinc-300 hover:bg-white/[0.08]'
                                    }`}
                                >
                                    {AUDIO_EQUALIZER_PRESET_LABELS[presetId] ?? presetId}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Live Frequency Response Curve Preview */}
                <div className="rounded-2xl border border-white/10 bg-black/40 p-3">
