                                                    {line.romanization}
                                                </p>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        )}

                        {/* Inline Visualizer Style Selector Strip in Lyrics Mode (works in both portrait and landscape) */}
                        <VisualizerStyleSelectorStrip
