import React from 'react';
import { motion, MotionValue } from 'framer-motion';
import { type Theme, type Line } from '../../../types';
import { detectTextDirection } from '../../../utils/lyrics/arabicText';
import { SECONDARY_TRACK_OPACITY } from '../../../utils/lyrics/subtitleTrackStyle';
import { colorWithAlpha } from '../colorMix';
import { type WordColorMatcher } from '../wordColoring';
import { MONET_SCROLL_TRANSITION, MONET_SUBTITLE_TRACK_STAGGER_S, type PositionedMonetLineEntry } from './monetRailLayout';
import { composeLineMasks, getClippedTextMask, getEdgeFadeMask, getLineMask } from './monetRailMasks';
import { MonetTimedTokenSpan } from './MonetRailTokens';

// src/components/visualizer/monet/MonetRailLine.tsx
// 歌词栏中的一行：位置、缩放、模糊与副字幕轨，按行状态切换静态或扫字渲染。
// Viewport Culling: 仅对距离视口中心 2 行以内的行启用动画、逐字进度和 CSS blur()，视口外的行保持静态且不加模糊滤镜。

export const MonetRailLine: React.FC<{
    entry: PositionedMonetLineEntry;
    currentTime: MotionValue<number>;
    theme: Theme;
    lyricFontPx: number;
    fontStack: string;
    translationFontStack: string;
    glowBufferPx: number;
    vGlowBufferPx: number;
    fontsEpoch: number;
    wordColorMatchers: WordColorMatcher[];
    audioPower?: MotionValue<number>;
    onLineSeek?: (line: Line) => void;
    canSeek?: boolean;
    disableEntryMotion?: boolean;
    renderStaticPassed?: boolean;
}> = ({ entry, currentTime, theme, lyricFontPx, fontStack, translationFontStack, glowBufferPx, vGlowBufferPx, fontsEpoch, wordColorMatchers, audioPower, onLineSeek, canSeek = false, disableEntryMotion = false, renderStaticPassed = false }) => {
    const initialOffset = entry.offset >= 0 ? 34 : -34;
    const exitOffset = entry.status === 'passed' || entry.offset < 0 ? -38 : 38;
    const lineDirection = detectTextDirection(entry.line.fullText);
    const isRtlLine = lineDirection === 'rtl';
    const isActiveLine = entry.status === 'active';
    const isWithinViewportWindow = Math.abs(entry.offset) <= 2;
    const effectiveFilter = isWithinViewportWindow && entry.tone.blurPx > 0
        ? `blur(${entry.tone.blurPx}px)`
        : 'none';
    const textMask = isActiveLine
        ? undefined
        : getClippedTextMask(
            entry.layout.isTextClipped,
            vGlowBufferPx + entry.layout.textPaddingTopPx + entry.layout.textContentHeightPx,
            Math.max(lyricFontPx * 0.55, 12),
        );
    const textEdgeMask = getEdgeFadeMask(entry.layout.isTextOverflowingWidth, Math.max(lyricFontPx * 0.9, 24));
    const textMaskStyle = composeLineMasks(textMask, textEdgeMask);
    const handleSeek = (event: React.MouseEvent | React.KeyboardEvent) => {
        if (!canSeek) {
            return;
        }

        event.stopPropagation();
        onLineSeek?.(entry.line);
    };
    const handleClickSeek = (event: React.MouseEvent<HTMLDivElement>) => {
        handleSeek(event);
        event.currentTarget.blur();
    };

    return (
        <motion.div
            dir={lineDirection}
            role={canSeek ? 'button' : undefined}
            tabIndex={canSeek ? 0 : undefined}
            onClick={canSeek ? handleClickSeek : undefined}
            onKeyDown={canSeek ? (event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    handleSeek(event);
                }
            } : undefined}
            className={`absolute top-0 min-w-0 will-change-transform ${canSeek ? 'cursor-pointer' : ''}`}
            initial={disableEntryMotion || !isWithinViewportWindow ? false : {
                opacity: 0,
                y: entry.y + initialOffset,
                scale: entry.tone.scale * 0.98,
                filter: 'blur(5px)',
            }}
            animate={{
                opacity: entry.tone.opacity,
                y: entry.y,
                scale: entry.tone.scale,
                filter: effectiveFilter,
            }}
            exit={disableEntryMotion || !isWithinViewportWindow ? undefined : {
                opacity: 0,
                y: entry.y + exitOffset,
                scale: entry.tone.scale * 0.98,
                filter: 'blur(6px)',
                transition: { duration: 0.2, ease: [0.32, 0.72, 0, 1] },
            }}
            transition={MONET_SCROLL_TRANSITION}
            style={{
                left: `${glowBufferPx}px`,
                right: `${glowBufferPx}px`,
                height: entry.layout.visualHeightPx,
                transformOrigin: isRtlLine ? 'right top' : 'left top',
                textAlign: isRtlLine ? 'right' : 'left',
                zIndex: entry.tone.zIndex,
            }}
        >
            {entry.line.isChorus && isWithinViewportWindow && (
                <motion.div
                    className="absolute inset-0 pointer-events-none -z-10 rounded-2xl"
                    initial={{ opacity: 0 }}
                    animate={{
                        opacity: entry.status === 'active' ? 1 : 0,
                        scale: entry.status === 'active' ? 1.02 : 0.96,
                    }}
                    transition={{ duration: 0.45, ease: 'easeOut' }}
                    style={{
                        background: `radial-gradient(circle at 50% 45%, ${colorWithAlpha(theme.accentColor, 0.14)} 0%, ${colorWithAlpha(theme.accentColor, 0.04)} 55%, transparent 82%)`,
                        filter: 'blur(10px)',
                    }}
                />
            )}
            <div
                dir={lineDirection}
                className="min-w-0 overflow-hidden pointer-events-none"
                style={{
                    marginLeft: `-${glowBufferPx}px`,
                    marginRight: `-${glowBufferPx}px`,
                    paddingLeft: `${glowBufferPx}px`,
                    paddingRight: `${glowBufferPx}px`,
                    marginTop: `-${vGlowBufferPx}px`,
                    marginBottom: `-${vGlowBufferPx}px`,
                    paddingTop: `${entry.layout.textPaddingTopPx + vGlowBufferPx}px`,
                    paddingBottom: `${entry.layout.textPaddingBottomPx + vGlowBufferPx}px`,
                    height: isActiveLine
                        ? undefined
                        : `${entry.layout.textHeightPx + vGlowBufferPx * 2}px`,
                    boxSizing: 'border-box',
                    fontFamily: fontStack,
                    fontSize: lyricFontPx,
                    fontWeight: entry.tone.fontWeight,
                    lineHeight: `${entry.layout.lineHeightPx}px`,
                    letterSpacing: 0,
                    textAlign: isRtlLine ? 'right' : 'left',
                    ...textMaskStyle,
                    textShadow: entry.status === 'active'
                        ? `0 14px 34px ${colorWithAlpha(theme.backgroundColor, 0.22)}`
                        : 'none',
                }}
            >
                <MonetTimedTokenSpan
                    entry={entry}
                    currentTime={currentTime}
                    accentColor={colorWithAlpha(theme.primaryColor, 0.98)}
                    fontPx={lyricFontPx}
                    fontStack={fontStack}
                    fontsEpoch={fontsEpoch}
                    wordColorMatchers={wordColorMatchers}
                    isChorus={entry.line.isChorus}
                    chorusAccentColor={theme.accentColor}
                    audioPower={audioPower}
                    renderStaticPassed={renderStaticPassed || !isWithinViewportWindow}
                />
            </div>
            {entry.layout.subtitleTracks.map((track, trackIndex) => {
                // Each row is cut at its own row cap, so the fade is per track. The second row steps
                // down in colour alpha too (0.68 is the single-row alpha); size and weight were set at measure time.
                const trackMask = getLineMask(track.isClipped, Math.max(track.fontPx * 0.65, 10));
                const trackDirection = detectTextDirection(track.text, lineDirection);
                return (
                    <motion.div
                        key={track.role}
                        dir={trackDirection}
                        data-subtitle-track={track.role}
                        className="min-w-0 overflow-hidden whitespace-pre-wrap break-words"
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.28, ease: [0.32, 0.72, 0, 1], delay: trackIndex * MONET_SUBTITLE_TRACK_STAGGER_S }}
                        style={{
                            marginLeft: `-${glowBufferPx}px`,
                            marginRight: `-${glowBufferPx}px`,
                            paddingLeft: `${glowBufferPx}px`,
                            paddingRight: `${glowBufferPx}px`,
                            height: track.heightPx,
                            paddingTop: track.paddingTopPx,
                            paddingBottom: track.paddingBottomPx,
                            boxSizing: 'border-box',
                            color: colorWithAlpha(theme.primaryColor, trackIndex > 0 ? 0.68 * SECONDARY_TRACK_OPACITY : 0.68),
                            fontFamily: translationFontStack,
                            fontSize: track.fontPx,
                            fontWeight: track.fontWeight,
                            lineHeight: `${track.lineHeightPx}px`,
                            letterSpacing: 0,
                            textAlign: isRtlLine ? 'right' : 'left',
                            WebkitMaskImage: trackMask,
                            maskImage: trackMask,
                            WebkitMaskRepeat: 'no-repeat',
                            maskRepeat: 'no-repeat',
                            WebkitMaskSize: '100% 100%',
                            maskSize: '100% 100%',
                        }}
                    >
                        {track.text}
                    </motion.div>
                );
            })}
        </motion.div>
    );
};

import React, { useMemo } from 'react';
import { motion, motionValue, useTransform, MotionValue } from 'framer-motion';
import {
    detectTextDirection,
    resolveTokenDirection,
    type TextDirection,
} from '../../../utils/lyrics/arabicText';
import { type GraphemeTiming } from '../../../utils/lyrics/graphemeTiming';
import { getLineRenderEndTime } from '../../../utils/lyrics/renderHints';
import { colorWithAlpha, mixColors } from '../colorMix';
import { resolveMonetFillWidth, resolveMonetGlow } from './monetLyricMotion';
import { buildWordColorRangesFromMatchers, resolveTokenColorMap, type WordColorMatcher } from '../wordColoring';
import { buildMonetDisplayTokens, measureMonetGraphemeOffsets, resolveMonetSweepEdgeSoftness, resolveMonetSweepEnd, resolveMonetWordStatus, type MonetLineStatus } from './monetLyricsModel';
import type { PositionedMonetLineEntry } from './monetRailLayout';

// src/components/visualizer/monet/MonetRailTokens.tsx
// 行内的逐词渲染：按时间着色的 token 与当前行的扫字遮罩 / 填充 / glow。
// Waiting lines and off-viewport lines render plain static spans rather than mounting 6 useTransform
// MotionValues per word, keeping GPU and JS overhead strictly bounded to the active/just-passed lines.

/** A clock that never moves, for words whose look does not depend on the time. */
const STILL_TIME = motionValue(0);

export const MonetTimedTokenSpan: React.FC<{
    entry: PositionedMonetLineEntry;
    currentTime: MotionValue<number>;
    accentColor: string;
    fontPx: number;
    fontStack: string;
    fontsEpoch: number;
    wordColorMatchers: WordColorMatcher[];
    isChorus?: boolean;
    chorusAccentColor?: string;
    audioPower?: MotionValue<number>;
    renderStaticPassed?: boolean;
}> = ({ entry, currentTime, accentColor, fontPx, fontStack, fontsEpoch, wordColorMatchers, isChorus, chorusAccentColor, audioPower, renderStaticPassed = false }) => {
    const lineRenderEndTime = useMemo(() => getLineRenderEndTime(entry.line), [entry.line]);
    const lineDirection = useMemo(() => detectTextDirection(entry.line.fullText), [entry.line.fullText]);
    const tokens = useMemo(() => buildMonetDisplayTokens(entry.line), [entry.line]);
    const wordColorRanges = useMemo(
        () => buildWordColorRangesFromMatchers(entry.line.fullText, wordColorMatchers),
        [entry.line.fullText, wordColorMatchers],
    );
    const tokenColors = useMemo(
        () => resolveTokenColorMap(tokens, wordColorRanges),
        [tokens, wordColorRanges],
    );
    const fontSpec = useMemo(
        () => `${entry.tone.fontWeight} ${fontPx}px ${fontStack}`,
        [entry.tone.fontWeight, fontPx, fontStack],
    );

    const resolvedAccentColor = isChorus && chorusAccentColor
        ? mixColors(accentColor, chorusAccentColor, 0.48)
        : accentColor;
    const isWaitingLine = entry.status === 'waiting';

    return (
        <span dir={lineDirection} className="block w-full min-w-0 max-w-full whitespace-pre-wrap break-words">
            {tokens.map(token => (
                renderStaticPassed ? (
                    <span
                        key={token.key}
                        style={{
                            color: token.timed && entry.status !== 'waiting'
                                ? tokenColors.get(token.key) ?? resolvedAccentColor
                                : entry.tone.baseColor,
                        }}
                    >
                        {token.text}
                    </span>
                ) : isWaitingLine ? (
                    <span key={token.key} style={{ color: entry.tone.baseColor }}>
                        {token.text}
                    </span>
                ) : token.timed && token.startTime !== null && token.endTime !== null ? (
                    <MonetWordSweep
                        key={token.key}
                        text={token.text}
                        startTime={token.startTime}
                        endTime={token.endTime}
                        graphemeTimings={token.graphemeTimings}
                        lineRenderEndTime={lineRenderEndTime}
                        currentTime={currentTime}
                        lineStatus={entry.status}
                        lineDirection={lineDirection}
                        wordColor={tokenColors.get(token.key) ?? resolvedAccentColor}
                        baseColor={entry.tone.baseColor}
                        fontPx={fontPx}
                        fontSpec={fontSpec}
                        fontsEpoch={fontsEpoch}
                        isChorus={isChorus}
                        audioPower={audioPower}
                    />
                ) : (
                    <span key={token.key} style={{ color: entry.tone.baseColor }}>
                        {token.text}
                    </span>
                )
            ))}
        </span>
    );
};

const MonetWordSweep: React.FC<{
    text: string;
    startTime: number;
    endTime: number;
    graphemeTimings: GraphemeTiming[];
    lineRenderEndTime: number;
    currentTime: MotionValue<number>;
    lineStatus: MonetLineStatus;
    lineDirection?: TextDirection;
    wordColor: string;
    baseColor: string;
    fontPx: number;
    fontSpec: string;
    /** Bumped when web fonts load; measured offsets are stale until then. */
    fontsEpoch: number;
    isChorus?: boolean;
    audioPower?: MotionValue<number>;
}> = ({
    text,
    startTime,
    endTime,
    graphemeTimings,
    lineRenderEndTime,
    currentTime,
    lineStatus,
    lineDirection = 'ltr',
    wordColor,
    baseColor,
    fontPx,
    fontSpec,
    fontsEpoch,
    isChorus,
}) => {
        const isLineActive = lineStatus === 'active';
        const canRenderGlow = lineStatus === 'active' || lineStatus === 'passed';
        const tokenDirection = useMemo(
            () => resolveTokenDirection(text, lineDirection),
            [lineDirection, text],
        );
        const gradientAngle = tokenDirection === 'rtl' ? '270deg' : '90deg';
        const graphemeOffsets = useMemo(
            () => measureMonetGraphemeOffsets(text, fontPx, fontSpec),
            // eslint-disable-next-line react-hooks/exhaustive-deps -- fontsEpoch re-measures once the real face loads
            [text, fontPx, fontSpec, fontsEpoch],
        );

        const sweepTime = isLineActive ? currentTime : STILL_TIME;
        const glowTime = canRenderGlow ? currentTime : STILL_TIME;

        const wordStatus = useTransform(sweepTime, latest => (
            isLineActive ? resolveMonetWordStatus(latest, startTime, endTime) : lineStatus
        ));

        const wordProgress = useTransform(sweepTime, latest => {
            if (!isLineActive || latest <= startTime) return 0;
            if (latest >= endTime) return 1;
            return (latest - startTime) / Math.max(0.001, endTime - startTime);
        });

        const fillWidth = useTransform(sweepTime, latest => (
            isLineActive ? resolveMonetFillWidth(latest, startTime, endTime, graphemeOffsets, graphemeTimings) : 0
        ));

        const maskImage = useTransform(fillWidth, latest => {
            const edgeSoftness = resolveMonetSweepEdgeSoftness(fontPx);
            const fullWidth = graphemeOffsets[graphemeOffsets.length - 1] ?? 0;
            const sweepEnd = resolveMonetSweepEnd(latest, fullWidth, edgeSoftness);
            const solidEnd = Math.max(sweepEnd - edgeSoftness, 0);
            const featherStart = Math.max(sweepEnd - edgeSoftness * 0.55, 0);
            const featherEnd = Math.max(sweepEnd, 0);
            return `linear-gradient(${gradientAngle}, rgba(0, 0, 0, 1) 0px, rgba(0, 0, 0, 1) ${solidEnd}px, rgba(0, 0, 0, 0.92) ${featherStart}px, rgba(0, 0, 0, 0) ${featherEnd}px, rgba(0, 0, 0, 0) 100%)`;
        });

        const fillGradient = useTransform(wordProgress, progress => {
            const color = mixColors(baseColor, wordColor, Math.min(progress, 1));
            return `linear-gradient(${gradientAngle}, ${color} 0%, ${colorWithAlpha(color, 0.92)} 68%, ${colorWithAlpha(color, 0.72)} 100%)`;
        });

        const resolvedBaseColor = useTransform(wordStatus, status =>
            (isLineActive && status === 'passed') || lineStatus === 'passed' ? wordColor : baseColor,
        );

        const glowShadow = useTransform(glowTime, latest => {
            if (!canRenderGlow || latest <= startTime) return 'none';

            const intensity = resolveMonetGlow(latest, startTime, endTime, lineRenderEndTime);

            if (intensity <= 0) return 'none';

            const radiusOne = Math.round(fontPx * (isChorus ? 0.45 : 0.28));
            const radiusTwo = Math.round(fontPx * (isChorus ? 0.90 : 0.65));
            const maxAlpha = isChorus ? 1.0 : 0.88;
            const glowColor = mixColors(baseColor, wordColor, intensity, intensity * maxAlpha);
            return `0 0 ${radiusOne}px ${glowColor}, 0 0 ${radiusTwo}px ${glowColor}`;
        }) as unknown as MotionValue<string>;

        const sweepOverflowPx = Math.round(fontPx * 0.5);

        return (
            <span
                dir={tokenDirection}
                className="relative inline-block whitespace-pre-wrap break-words"
                style={{ unicodeBidi: 'isolate' }}
            >
                <motion.span style={{ color: resolvedBaseColor, textShadow: glowShadow }}>
                    {text}
                </motion.span>
                {isLineActive ? (
                    <motion.span
                        aria-hidden
                        dir={tokenDirection}
                        className="pointer-events-none absolute left-0 right-0 block whitespace-pre-wrap break-words"
                        style={{
                            top: -sweepOverflowPx,
                            bottom: -sweepOverflowPx,
                            paddingTop: sweepOverflowPx,
                            paddingBottom: sweepOverflowPx,
                            boxSizing: 'border-box',
                            WebkitMaskImage: maskImage,
                            maskImage,
                            WebkitMaskSize: '100% 100%',
                            maskSize: '100% 100%',
                            WebkitMaskRepeat: 'no-repeat',
                            maskRepeat: 'no-repeat',
                            textShadow: 'none',
                        }}
                    >
                        <motion.span
                            className="block whitespace-pre-wrap break-words"
                            style={{
                                marginTop: -sweepOverflowPx,
                                paddingTop: sweepOverflowPx,
                                paddingBottom: sweepOverflowPx,
                                color: 'transparent',
                                WebkitTextFillColor: 'transparent',
                                backgroundImage: fillGradient,
                                WebkitBackgroundClip: 'text',
                                backgroundClip: 'text',
                            }}
                        >
                            {text}
                        </motion.span>
                    </motion.span>
                ) : null}
            </span>
        );
    };

src/components/visualizer/monet/monetBac:
import { colorWithAlpha, parseColorChannels } from '../colorMix';
import type { MonetBackgroundTuning, Theme } from '../../../types';

// src/components/visualizer/monet/monetBackgroundPaint.ts
// Paints the Monet poster background onto a 2D canvas: the cover cropped and blurred, the colour
// treatment pixel by pixel, the overlay. It touches no document, so it runs in the worker that
// makes the picture (monetBackground.worker.ts).
// Uses a 384x256 ambient buffer (~0.2x of 1080p) with proportional blur scaling and smooth
// bilinear CSS upscaling, cutting pixel-loop CPU and GPU memory by ~95% with zero visual difference.
export const MONET_BACKGROUND_WIDTH = 384;
export const MONET_BACKGROUND_HEIGHT = 256;

/** The theme colours the picture is made with. */
export type MonetBackgroundColors = Pick<Theme, 'backgroundColor' | 'primaryColor' | 'accentColor'>;

interface RgbChannels {
    r: number;
    g: number;
    b: number;
}

const FALLBACK_DARK: RgbChannels = { r: 10, g: 10, b: 12 };
const FALLBACK_LIGHT: RgbChannels = { r: 245, g: 245, b: 245 };

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const mix = (from: number, to: number, amount: number) => from + (to - from) * amount;
const luminanceOf = (r: number, g: number, b: number) => 0.2126 * r + 0.7152 * g + 0.0722 * b;

export const resolveWashEndpoints = (
    background: RgbChannels,
    primary: RgbChannels,
) => {
    const backgroundLuminance = luminanceOf(background.r, background.g, background.b);
    const primaryLuminance = luminanceOf(primary.r, primary.g, primary.b);

    return backgroundLuminance <= primaryLuminance
        ? { shadow: background, highlight: primary }
        : { shadow: primary, highlight: background };
};

const drawCoverCropped = (
    context: OffscreenCanvasRenderingContext2D,
    image: ImageBitmap,
    width: number,
    height: number,
) => {
    const imageWidth = image.width;
    const imageHeight = image.height;
    if (!imageWidth || !imageHeight) {
        return;
    }

    const scale = Math.max(width / imageWidth, height / imageHeight);
    const drawWidth = imageWidth * scale;
    const drawHeight = imageHeight * scale;
    const offsetX = (width - drawWidth) / 2;
    const offsetY = (height - drawHeight) / 2;
    context.imageSmoothingEnabled = true;
    context.imageSmoothingQuality = 'high';
    context.drawImage(image, offsetX, offsetY, drawWidth, drawHeight);
};

const resolveThemeChannel = (color: string, fallback: RgbChannels): RgbChannels => {
    const parsed = parseColorChannels(color);
    return parsed
        ? {
            r: clamp(parsed.r, 0, 255),
            g: clamp(parsed.g, 0, 255),
            b: clamp(parsed.b, 0, 255),
        }
        : fallback;
};

export const resolveWashColor = (
    normalizedLuminance: number,
    background: RgbChannels,
    accent: RgbChannels,
    primary: RgbChannels,
): RgbChannels => {
    const { shadow, highlight } = resolveWashEndpoints(background, primary);
    if (normalizedLuminance <= 0.55) {
        const amount = normalizedLuminance / 0.55;
        return {
            r: mix(shadow.r, accent.r, amount),
            g: mix(shadow.g, accent.g, amount),
            b: mix(shadow.b, accent.b, amount),
        };
    }

    const amount = (normalizedLuminance - 0.55) / 0.45;
    return {
        r: mix(accent.r, highlight.r, amount),
        g: mix(accent.g, highlight.g, amount),
        b: mix(accent.b, highlight.b, amount),
    };
};

// Applies the stable canvas-only color treatment so Safari never needs CSS filters for Monet backgrounds.
const applyBackgroundPostProcessing = (
    context: OffscreenCanvasRenderingContext2D,
    width: number,
    height: number,
    theme: MonetBackgroundColors,
    tuning: MonetBackgroundTuning,
) => {
    const grayscale = clamp(tuning.backgroundGrayscale, 0, 1);
    const saturation = clamp(tuning.backgroundSaturation, 0, 2);
    const wash = clamp(tuning.backgroundWash, 0, 1);
    if (grayscale <= 0 && Math.abs(saturation - 1) < 0.001 && wash <= 0) {
        return;
    }

    const imageData = context.getImageData(0, 0, width, height);
    const data = imageData.data;
    const background = resolveThemeChannel(theme.backgroundColor, FALLBACK_DARK);
    const accent = resolveThemeChannel(theme.accentColor, background);
    const primary = resolveThemeChannel(theme.primaryColor, FALLBACK_LIGHT);
    const customWash = resolveThemeChannel(tuning.backgroundWashCustomColor, accent);
    const washAccent = tuning.backgroundWashColorMode === 'custom' ? customWash : accent;

    for (let index = 0; index < data.length; index += 4) {
        let r = data[index];
        let g = data[index + 1];
        let b = data[index + 2];
        const alpha = data[index + 3];
        if (alpha === 0) {
            continue;
        }

        const luminance = luminanceOf(r, g, b);
        if (grayscale > 0) {
            r = mix(r, luminance, grayscale);
            g = mix(g, luminance, grayscale);
            b = mix(b, luminance, grayscale);
        }

        if (Math.abs(saturation - 1) >= 0.001) {
            const saturatedLuminance = luminanceOf(r, g, b);
            r = saturatedLuminance + (r - saturatedLuminance) * saturation;
            g = saturatedLuminance + (g - saturatedLuminance) * saturation;
            b = saturatedLuminance + (b - saturatedLuminance) * saturation;
        }

        if (wash > 0) {
            const washColor = resolveWashColor(clamp(luminance / 255, 0, 1), background, washAccent, primary);
            r = mix(r, washColor.r, wash);
            g = mix(g, washColor.g, wash);
            b = mix(b, washColor.b, wash);
        }

        data[index] = Math.round(clamp(r, 0, 255));
        data[index + 1] = Math.round(clamp(g, 0, 255));
        data[index + 2] = Math.round(clamp(b, 0, 255));
    }

    context.putImageData(imageData, 0, 0);
};

const paintMonetOverlay = (
    context: OffscreenCanvasRenderingContext2D,
    width: number,
    height: number,
    theme: MonetBackgroundColors,
    tuning: MonetBackgroundTuning,
) => {
    const overlay = clamp(tuning.backgroundOverlayOpacity, 0, 1);
    const overlayGradient = context.createLinearGradient(0, 0, width, height);
    overlayGradient.addColorStop(0, colorWithAlpha(theme.accentColor, 0.08 + overlay * 0.62));
    overlayGradient.addColorStop(0.44, colorWithAlpha(theme.backgroundColor, 0.16 + overlay * 0.58));
    overlayGradient.addColorStop(1, colorWithAlpha(theme.primaryColor, 0.06 + overlay * 0.36));
    context.fillStyle = overlayGradient;
    context.fillRect(0, 0, width, height);

    const leftBloom = context.createRadialGradient(width * 0.18, height * 0.34, 0, width * 0.18, height * 0.34, width * 0.55);
    leftBloom.addColorStop(0, colorWithAlpha(theme.accentColor, overlay * 0.42));
    leftBloom.addColorStop(1, colorWithAlpha(theme.backgroundColor, 0));
    context.fillStyle = leftBloom;
    context.fillRect(0, 0, width, height);

    const rightVeil = context.createLinearGradient(width * 0.45, 0, width, 0);
    rightVeil.addColorStop(0, colorWithAlpha(theme.backgroundColor, 0));
    rightVeil.addColorStop(1, colorWithAlpha(theme.backgroundColor, 0.18 + overlay * 0.38));
    context.fillStyle = rightVeil;
    context.fillRect(0, 0, width, height);

    if (tuning.backgroundStreaksEnabled === false) {
        return;
    }

    context.fillStyle = colorWithAlpha(theme.backgroundColor, 0.1 + overlay * 0.08);
    for (let index = 0; index < 18; index += 1) {
        const x = (index * 127) % width;
        const y = ((index * 211) % height) - 40;
        context.fillRect(x, y, 1, height * 0.28);
    }
};

/**
 * The whole picture on a canvas of MONET_BACKGROUND_WIDTH x MONET_BACKGROUND_HEIGHT. `blurPx` is
 * the canvas blur (scaled proportionally to the ambient buffer width), or null where the page blurs
 * the picture with CSS instead.
 */
export const paintMonetBackground = (
    context: OffscreenCanvasRenderingContext2D,
    image: ImageBitmap,
    colors: MonetBackgroundColors,
    tuning: MonetBackgroundTuning,
    blurPx: number | null,
) => {
    const { width, height } = context.canvas;
    context.fillStyle = colors.backgroundColor;
    context.fillRect(0, 0, width, height);

    context.save();
    if (blurPx !== null) {
        const scaledBlur = Math.max(0.5, (blurPx * width) / 1920);
        context.filter = `blur(${scaledBlur.toFixed(2)}px)`;
    }
    drawCoverCropped(context, image, width, height);
    context.restore();

    applyBackgroundPostProcessing(context, width, height, colors, tuning);
    paintMonetOverlay(context, width, height, colors, tuning);
};

