import { type Theme, type Line } from '../../../types';
import { colorWithAlpha } from '../colorMix';
import { resolveWordColor } from '../wordColoring';
import { MONET_SCROLL_SPRING, MONET_SCALE_SPRING } from './monetLyricMotion';
import { buildMonetLayoutCacheKey, measureMonetLineLayout, type MonetLineLayoutInputs, type MonetLineStatus, type MonetMeasuredLineLayout, type MonetVisibleLineEntry } from './monetLyricsModel';
import { rememberBounded } from '../textMeasureCache';

// src/components/visualizer/monet/monetRailLayout.ts
// Monet 歌词栏的排布：栏尺寸与间距常量、行色调与状态、可滚动条目、测量缓存，以及按固定轨道算出的行位置。

export interface MonetRailSize {
    width: number;
    height: number;
}

interface MonetLineTone {
    opacity: number;
    scale: number;
    blurPx: number;
    baseColor: string;
    fontWeight: number;
    zIndex: number;
}

export interface PositionedMonetLineEntry extends MonetVisibleLineEntry {
    y: number;
    tone: MonetLineTone;
    layout: MonetMeasuredLineLayout;
    scaledHeight: number;
}

export type MonetLayoutCache = Map<string, MonetMeasuredLineLayout>;

const MONET_RAIL_WIDTH_FALLBACK_PX = 680;
const MONET_RAIL_HEIGHT_FALLBACK_PX = 340;
// Stagger between subtitle rows when they fade in, so the second row reads as following the first.
export const MONET_SUBTITLE_TRACK_STAGGER_S = 0.04;
const MONET_ACTIVE_GAP_PX = 18;
const MONET_INACTIVE_GAP_PX = 14;
export const MONET_RAIL_MIN_ROWS = 7;
const MONET_ACTIVE_GAP_RATIO = 0.49;
const MONET_INACTIVE_GAP_RATIO = 0.38;
export const MONET_SCROLL_IDLE_RESET_MS = 1800;
export const MONET_SCROLL_STEP_PX = 72;
export const MONET_TOUCH_STEP_PX = 52;
const MONET_SCROLL_BEFORE = 4;
const MONET_SCROLL_AFTER = 4;
const MONET_LAYOUT_CACHE_LIMIT = 240;
export const MONET_RAIL_SCROLL_EVENT_OPTIONS: AddEventListenerOptions = { passive: false };
export const MONET_SCROLL_TRANSITION = {
    y: { type: 'spring', ...MONET_SCROLL_SPRING },
    scale: { type: 'spring', ...MONET_SCALE_SPRING },
    opacity: { duration: 0.28, ease: [0.32, 0.72, 0, 1] },
    filter: { duration: 0.32, ease: [0.32, 0.72, 0, 1] },
} as const;
export const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
export const clampScrollSteps = (steps: number) => Math.max(-1, Math.min(1, steps));
export const getScrollDirection = (delta: number) => (delta === 0 ? 0 : delta > 0 ? 1 : -1);

export const resolveMonetWordColor = (
    wordText: string,
    theme: Theme,
    fallbackColor: string,
    keywordColoringEnabled = true,
): string => {
    return resolveWordColor(wordText, theme.wordColors, fallbackColor, {
        keywordColoringEnabled,
        cjkMatchMode: 'exact',
    });
};

const resolveLineTone = (
    entry: MonetVisibleLineEntry,
    theme: Theme,
    inactiveScale: number,
): MonetLineTone => {
    if (entry.status === 'active') {
        return {
            opacity: 1,
            scale: 1,
            blurPx: 0,
            baseColor: colorWithAlpha(theme.primaryColor, 0.34),
            fontWeight: 600,
            zIndex: 4,
        };
    }

    const distance = Math.max(Math.abs(entry.offset), 1);
    const isWaiting = entry.status === 'waiting';
    const scale = clamp(inactiveScale * Math.pow(0.9, distance - 1), 0.68, 0.92);
    // Viewport Culling: only apply CSS filter blur to lines within 2 lines of the viewport anchor;
    // lines beyond 2 lines remain un-blurred (blurPx = 0) so off-viewport lines allocate no GPU filter surfaces.
    const blurPx = distance > 2
        ? 0
        : isWaiting
            ? (distance === 1 ? 0.7 : 1.8)
            : (1.1 + (distance - 1) * 0.7);

    return {
        opacity: isWaiting
            ? clamp(0.72 - (distance - 1) * 0.18, 0.36, 0.72)
            : clamp(0.52 - (distance - 1) * 0.12, 0.28, 0.52),
        scale,
        blurPx,
        baseColor: colorWithAlpha(theme.primaryColor, isWaiting ? 0.46 : 0.36),
        fontWeight: 500,
        zIndex: isWaiting ? 3 - distance : 2 - distance,
    };
};

const resolveLineGap = (
    previous: PositionedMonetLineEntry,
    next: PositionedMonetLineEntry,
    lyricFontPx: number,
): number => (
    previous.status === 'active' || next.status === 'active'
        ? Math.max(MONET_ACTIVE_GAP_PX, lyricFontPx * MONET_ACTIVE_GAP_RATIO)
        : Math.max(MONET_INACTIVE_GAP_PX, lyricFontPx * MONET_INACTIVE_GAP_RATIO)
);

const resolveRailLineStatus = (lineIndex: number, activeLineIndex: number): MonetLineStatus => {
    if (lineIndex === activeLineIndex) {
        return 'active';
    }
    if (activeLineIndex >= 0 && lineIndex < activeLineIndex) {
        return 'passed';
    }
    return 'waiting';
};

export const buildScrollableRailEntries = (
    lines: Line[],
    anchorIndex: number,
    activeLineIndex: number,
): MonetVisibleLineEntry[] => {
    if (lines.length === 0) {
        return [];
    }

    const safeAnchorIndex = Math.round(clamp(anchorIndex, 0, lines.length - 1));
    const startIndex = Math.max(0, safeAnchorIndex - MONET_SCROLL_BEFORE);
    const endIndex = Math.min(lines.length - 1, safeAnchorIndex + MONET_SCROLL_AFTER);
    const nextEntries: MonetVisibleLineEntry[] = [];

    for (let index = startIndex; index <= endIndex; index += 1) {
        const line = lines[index];
        nextEntries.push({
            key: `${index}-${line.startTime}-${line.fullText}`,
            line,
            index,
            offset: index - safeAnchorIndex,
            status: resolveRailLineStatus(index, activeLineIndex),
        });
    }

    return nextEntries;
};

const getOrMeasureMonetLineLayout = (
    cache: MonetLayoutCache,
    entry: MonetVisibleLineEntry,
    inputs: MonetLineLayoutInputs,
) => {
    const cacheKey = buildMonetLayoutCacheKey(entry, inputs);
    const cached = cache.get(cacheKey);
    if (cached) {
        return cached;
    }

    const layout = measureMonetLineLayout({
        line: entry.line,
        status: entry.status,
        ...inputs,
    });
    return rememberBounded(cache, cacheKey, layout, MONET_LAYOUT_CACHE_LIMIT);
};

export const buildPositionedEntries = (
    entries: MonetVisibleLineEntry[],
    railSize: MonetRailSize,
    theme: Theme,
    lyricFontPx: number,
    inactiveFontPx: number,
    layoutInputs: Omit<MonetLineLayoutInputs, 'fontPx' | 'maxWidthPx'>,
    glowBufferPx: number,
    layoutCache: MonetLayoutCache,
): PositionedMonetLineEntry[] => {
    const railWidth = railSize.width || MONET_RAIL_WIDTH_FALLBACK_PX;
    const railHeight = railSize.height || MONET_RAIL_HEIGHT_FALLBACK_PX;
    const inactiveScale = clamp(inactiveFontPx / Math.max(lyricFontPx, 1), 0.72, 0.92);
    const contentWidthPx = Math.max(railWidth - glowBufferPx * 2, 0);
    const measureInputs: MonetLineLayoutInputs = {
        ...layoutInputs,
        fontPx: lyricFontPx,
        maxWidthPx: contentWidthPx - 8,
    };

    const measuredEntries: PositionedMonetLineEntry[] = entries.map(entry => {
        const tone = {
            ...resolveLineTone(entry, theme, inactiveScale),
            fontWeight: layoutInputs.fontWeight,
        };
        const layout = getOrMeasureMonetLineLayout(layoutCache, entry, measureInputs);

        return {
            ...entry,
            y: 0,
            tone,
            layout,
            scaledHeight: layout.visualHeightPx * tone.scale,
        };
    });

    if (measuredEntries.length === 0) {
        return [];
    }

    const anchorIndex = Math.max(0, measuredEntries.findIndex(entry => entry.offset === 0));
    const focusCenterY = railHeight * 0.46;
    measuredEntries[anchorIndex].y = focusCenterY - measuredEntries[anchorIndex].scaledHeight / 2;

    for (let index = anchorIndex + 1; index < measuredEntries.length; index += 1) {
        const previous = measuredEntries[index - 1];
        const current = measuredEntries[index];
        current.y = previous.y + previous.scaledHeight + resolveLineGap(previous, current, lyricFontPx);
    }

    for (let index = anchorIndex - 1; index >= 0; index -= 1) {
        const current = measuredEntries[index];
        const next = measuredEntries[index + 1];
        current.y = next.y - current.scaledHeight - resolveLineGap(current, next, lyricFontPx);
    }

    return measuredEntries;
};

src/components/visualizer/pendolo/Pendol:
import { resolveMobileCanvasDpr } from '../../../utils/mobileVisualizerBudget';
import { isAppForegroundVisible, subscribeAppForegroundVisibility } from '../../../utils/visualizerVisibilityGate';
import React, { useEffect, useMemo, useRef } from 'react';
import type { MotionValue } from 'framer-motion';
import {
    extractAssetIdFromCoverUrl,
    getCachedLocalCoverObjectUrl,
    resolveLocalCoverObjectUrl,
} from '../../../services/localCoverRuntime';
import { colorWithAlpha } from '../colorMix';
import { drawPendoloClockwork2d } from './pendoloClockworkDraw2d';
import {
    createPendoloBeatCounter,
    isPendoloBeatFxIdle,
    readPendoloBeatTriggers,
} from './pendoloBeatFx';
import { getBeatEffectStrength } from '../../../services/beatFx/beatFxLive';
import { BEAT_EFFECT_IDS } from '../../../services/beatFx/beatEffects';
import {
    drawPendoloBeatFxOverlay2d,
    drawPendoloWaveLens2d,
    type PendoloBeatFxDrawFrame,
} from './pendoloBeatFxDraw';
import {
    createPendoloClockworkMotionState,
    stepPendoloClockworkMotion,
    type PendoloClockworkBeatInput,
} from './pendoloClockworkMotion';
import type { PendoloMotionProfile } from './pendoloMotionProfile';
import {
    resolvePendoloClockworkBox,
    type PendoloClockworkFrameInput,
    type PendoloGearDecorMode,
} from './pendoloClockworkScene';
import { PendoloClockworkRenderer } from './pendoloClockworkWebGL';
import type { PendoloBeatFxShared } from './usePendoloBeatFx';

// src/components/visualizer/pendolo/PendoloClockworkCanvas.tsx

export interface PendoloClockworkCanvasProps {
    centerX: number;
    centerY: number;
    viewportWidth: number;
    viewportHeight: number;
    baseRadius: number;
    lyricRingRadius: number;
    escapementAngleMotionValue: MotionValue<number>;
    audioBassMotionValue?: MotionValue<number>;
    audioBass?: number;
    primaryTextColor: string;
    accentTextColor: string;
    backgroundColor?: string;
    showGearDecor: PendoloGearDecorMode;
    showCenterGradient?: boolean;
    showCover?: boolean;
    coverUrl?: string | null;
    enableLineGlow?: boolean;
    paused?: boolean;
    motionProfile: PendoloMotionProfile;
    /** 智能动感模式's beat effects (usePendoloBeatFx); nothing is drawn or stepped while inactive. */
    beatFxRef?: React.MutableRefObject<PendoloBeatFxShared>;
}

/**
 * PendoloClockworkCanvas: Renders dynamic wireframe clockwork gear train background.
 * PendoloClockworkCanvas: Wireframe clockwork gear train.
 * Prefers WebGL2; falls back to Canvas2D when unavailable.
 */
const PendoloClockworkCanvas: React.FC<PendoloClockworkCanvasProps> = ({
    centerX,
    centerY,
    viewportWidth,
    viewportHeight,
    baseRadius,
    lyricRingRadius,
    escapementAngleMotionValue,
    audioBassMotionValue,
    audioBass = 0.18,
    primaryTextColor,
    accentTextColor,
    backgroundColor = '#000000',
    showGearDecor,
    showCenterGradient = true,
    showCover = false,
    coverUrl = null,
    enableLineGlow = false,
    paused = false,
    motionProfile,
    beatFxRef,
}) => {
    const webglCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const canvas2dRef = useRef<HTMLCanvasElement | null>(null);
    const rendererRef = useRef<PendoloClockworkRenderer | null>(null);
    const useWebglRef = useRef(false);
    const motionStateRef = useRef(createPendoloClockworkMotionState());
    const lastTimestampRef = useRef<number | null>(null);
    const coverImageRef = useRef<HTMLImageElement | null>(null);
    // Beats for the gear train come from the clock through a counter of the canvas's own, so the
    // seconds gear and the balance step on the frame they fire, independent of the FX loop.
    const beatCounterRef = useRef(createPendoloBeatCounter());
    const beatTriggersRef = useRef(readPendoloBeatTriggers(createPendoloBeatCounter()));
    const beatInputRef = useRef<PendoloClockworkBeatInput>({ beats: 0, downbeats: 0, beatGain: 0, downbeatGain: 0 });
    const beatFxFrameRef = useRef<PendoloBeatFxDrawFrame | null>(null);
    const waveScratchRef = useRef<HTMLCanvasElement | null>(null);

    // The canvases cover only the clockwork, not the viewport; everything is drawn relative to
    // the box, so the frame's centre is shifted by its offset.
    const contentBox = useMemo(
        () => resolvePendoloClockworkBox(
            centerX,
            centerY,
            baseRadius,
            lyricRingRadius,
            viewportWidth,
            viewportHeight,
            showCenterGradient,
        ),
        [baseRadius, centerX, centerY, lyricRingRadius, showCenterGradient, viewportHeight, viewportWidth],
    );

    const propsRef = useRef({
        contentBox,
        centerX,
        centerY,
        baseRadius,
        lyricRingRadius,
        audioBass,
        primaryTextColor,
        accentTextColor,
        backgroundColor,
        showGearDecor,
        showCenterGradient,
        showCover,
        coverUrl,
        enableLineGlow,
        paused,
        motionProfile,
    });

    useEffect(() => {
        propsRef.current = {
            contentBox,
            centerX,
            centerY,
            baseRadius,
            lyricRingRadius,
            audioBass,
            primaryTextColor,
            accentTextColor,
            backgroundColor,
            showGearDecor,
            showCenterGradient,
            showCover,
            coverUrl,
            enableLineGlow,
            paused,
            motionProfile,
        };
    }, [
        contentBox, centerX, centerY, baseRadius, lyricRingRadius, audioBass,
        primaryTextColor, accentTextColor, backgroundColor, showGearDecor,
        showCenterGradient, showCover, coverUrl, enableLineGlow, paused, motionProfile,
    ]);

    useEffect(() => {
        // The previous song's cover must not stay on screen (or be uploaded under the new song)
        // while the new one loads.
        coverImageRef.current = null;
        if (!showCover || !coverUrl) return undefined;
        let cancelled = false;
        let img: HTMLImageElement | null = null;
        const startLoad = (effectiveCoverUrl: string) => {
            if (cancelled) return;
            // CORS first, like the other cover consumers: WebGL cannot upload a tainted image. A
            // host without CORS headers still gets a plain load, which the Canvas2D path can draw.
            const load = (crossOrigin: boolean) => {
                const next = new Image();
                if (crossOrigin && (effectiveCoverUrl.startsWith('http://') || effectiveCoverUrl.startsWith('https://'))) {
                    next.crossOrigin = 'anonymous';
                }
                next.onload = () => {
                    if (!cancelled) coverImageRef.current = next;
                };
                next.onerror = () => {
                    if (cancelled) return;
                    if (crossOrigin) load(false);
                    else coverImageRef.current = null;
                };
                next.src = effectiveCoverUrl;
                img = next;
            };
            load(true);
        };

        if (extractAssetIdFromCoverUrl(coverUrl)) {
            const cached = getCachedLocalCoverObjectUrl(coverUrl);
            if (cached) {
                startLoad(cached);
            } else {
                void resolveLocalCoverObjectUrl(coverUrl).then(resolved => {
                    startLoad(resolved || coverUrl);
                });
            }
        } else {
            startLoad(coverUrl);
        }

        return () => {
            cancelled = true;
            if (img) {
                img.onload = null;
                img.onerror = null;
            }
        };
    }, [coverUrl, showCover]);

    useEffect(() => {
        const webglCanvas = webglCanvasRef.current;
        // A renderer belongs to one canvas. Turning every layer off unmounts the canvases, and
        // turning one back on mounts new ones, so a renderer for any other canvas is dropped.
        if (rendererRef.current && rendererRef.current.canvas !== webglCanvas) {
            rendererRef.current.release();
            rendererRef.current = null;
            useWebglRef.current = false;
        }
        if (showGearDecor === 'none' && !showCenterGradient && !showCover) return undefined;

        const attachRenderer = () => {
            if (!webglCanvas || rendererRef.current) return;
            const created = new PendoloClockworkRenderer(webglCanvas);
            if (created.isReady) {
                rendererRef.current = created;
                useWebglRef.current = true;
                if (canvas2dRef.current) canvas2dRef.current.style.visibility = 'hidden';
            } else {
                created.release();
                useWebglRef.current = false;
                webglCanvas.style.visibility = 'hidden';
                if (canvas2dRef.current) canvas2dRef.current.style.visibility = 'visible';
            }
        };
        attachRenderer();

        // A lost context (GPU reset, driver update, too many contexts) draws with Canvas2D until
        // the browser restores it; preventDefault is what allows the restore.
        const handleContextLost = (event: Event) => {
            event.preventDefault();
            rendererRef.current?.dispose();
            rendererRef.current = null;
            useWebglRef.current = false;
        };
        const handleContextRestored = () => attachRenderer();
        webglCanvas?.addEventListener('webglcontextlost', handleContextLost);
        webglCanvas?.addEventListener('webglcontextrestored', handleContextRestored);

        let animationFrameId = 0;

        const render = (timestamp: number) => {
            if (!isAppForegroundVisible()) {
                animationFrameId = 0;
                lastTimestampRef.current = null;
                return;
            }
            const p = propsRef.current;
            if (p.showGearDecor === 'none' && !p.showCenterGradient && !p.showCover) return;

            if (lastTimestampRef.current === null) {
                lastTimestampRef.current = timestamp;
            }
            const dt = Math.min((timestamp - lastTimestampRef.current) / 1000, 0.05);
            lastTimestampRef.current = timestamp;

            const rawBass = audioBassMotionValue ? audioBassMotionValue.get() : p.audioBass;
            // The gears step on beat_this' beats only while 齿轮随拍 plays; it is retired (2026-10-17),
            // so they keep their own motion, and beat_this does not run for 时计 at all.
            const gearBeats = beatFxRef?.current.active && getBeatEffectStrength(BEAT_EFFECT_IDS.pendoloGearBeats) > 0;
            // What 仿真鼓面 lights on this canvas - the jewels, the tick and outer dials - is drawn whenever the
            // effect frame is active, not only under 齿轮随拍: gated on that retired effect, the drumhead's
            // jewels and dials were never drawn, only its DOM halo and shake (2026-10-18).
            const beatFx = beatFxRef?.current.active ? beatFxRef.current : null;
            let beatInput: PendoloClockworkBeatInput | null = null;
            if (gearBeats) {
                const triggers = readPendoloBeatTriggers(beatCounterRef.current, beatTriggersRef.current);
                beatInput = beatInputRef.current;
                beatInput.beats = triggers.beats;
                beatInput.downbeats = triggers.downbeats;
                beatInput.beatGain = triggers.beatGain;
                beatInput.downbeatGain = triggers.downbeatGain;
            } else {
                beatCounterRef.current.synced = false;
            }
            const motion = stepPendoloClockworkMotion(
                motionStateRef.current,
                dt,
                rawBass,
                p.paused,
                p.motionProfile,
                beatInput,
            );
            // 2. Main gear wheel angle is strictly tied to lyric line ratchet steps
            // Gears remain stationary while a line is being sung, and ratchet ONLY when lyrics switch
            const escapementAngle = escapementAngleMotionValue.get();

            const box = p.contentBox;
            const frame: PendoloClockworkFrameInput = {
                centerX: p.centerX - box.left,
                centerY: p.centerY - box.top,
                baseRadius: p.baseRadius,
                lyricRingRadius: p.lyricRingRadius,
                escapementAngle,
                phase: motion.phase,
                bassOscillation: motion.bassOscillation,
                secondGearAngle: motion.secondGearAngle,
                transBeatAngle: motion.transBeatAngle,
                primaryTextColor: p.primaryTextColor,
                accentTextColor: p.accentTextColor,
                backgroundColor: p.backgroundColor || '#000000',
                showGearDecor: p.showGearDecor,
                showCenterGradient: p.showCenterGradient,
                showCover: p.showCover,
                coverImage: coverImageRef.current,
            };

            // Between beats, with nothing lit or moving, the frame is drawn exactly as with the switch off.
            let fxFrame: PendoloBeatFxDrawFrame | null = null;
            if (beatFx && !(beatFx.wave === null && isPendoloBeatFxIdle(beatFx.state, beatFx.now))) {
                fxFrame = beatFxFrameRef.current ?? {
                    jewelFlare: 0,
                    smallJewelFlare: 0,
                    tickDialLight: 0,
                    outerDialLight: 0,
                    sparks: beatFx.state.sparks,
                    offsetX: 0,
                    offsetY: 0,
                    wave: null,
                    color: beatFx.color,
                };
                beatFxFrameRef.current = fxFrame;
                fxFrame.jewelFlare = beatFx.state.jewelFlare;
                fxFrame.smallJewelFlare = beatFx.state.smallJewelFlare;
                fxFrame.tickDialLight = beatFx.state.tickDialLight;
                fxFrame.outerDialLight = beatFx.state.outerDialLight;
                fxFrame.sparks = beatFx.state.sparks;
                fxFrame.offsetX = box.left;
                fxFrame.offsetY = box.top;
                fxFrame.wave = beatFx.wave;
                fxFrame.color = beatFx.color;
            }

            const width = box.width;
            const height = box.height;
            if (width <= 0 || height <= 0) {
                animationFrameId = window.requestAnimationFrame(render);
                return;
            }
            const dpr = resolveMobileCanvasDpr(window.devicePixelRatio);

            const renderer = rendererRef.current;
            if (useWebglRef.current && !renderer?.isReady) useWebglRef.current = false;
            // WebGL cannot upload a cover served without CORS headers, so frames that show such
            // a cover are drawn with Canvas2D, which can. The renderer stays attached.
            const coverNeeds2d = Boolean(
                frame.showCover && renderer?.isCoverRejected(frame.coverImage),
            );

            if (useWebglRef.current && renderer && !coverNeeds2d) {
                if (webglCanvasRef.current) webglCanvasRef.current.style.visibility = 'visible';
                if (canvas2dRef.current) canvas2dRef.current.style.visibility = 'hidden';
                // Glow comes from the same CSS drop-shadow as Canvas2D, so both backends match.
                renderer.draw({
                    input: frame,
                    cssWidth: width,
                    cssHeight: height,
                    dpr,
                    beatFx: fxFrame,
                });
            } else {
                if (webglCanvasRef.current) webglCanvasRef.current.style.visibility = 'hidden';
                const canvas = canvas2dRef.current;
                if (!canvas) {
                    animationFrameId = window.requestAnimationFrame(render);
                    return;
                }
                canvas.style.visibility = 'visible';
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    animationFrameId = window.requestAnimationFrame(render);
                    return;
                }
                const pixelWidth = Math.round(width * dpr);
                const pixelHeight = Math.round(height * dpr);
                if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
                    canvas.width = pixelWidth;
                    canvas.height = pixelHeight;
                }
                ctx.save();
                ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
                ctx.clearRect(0, 0, width, height);
                drawPendoloClockwork2d(ctx, frame);
                if (fxFrame) {
                    if (fxFrame.wave) {
                        waveScratchRef.current ??= document.createElement('canvas');
                        drawPendoloWaveLens2d(ctx, canvas, waveScratchRef.current, frame, fxFrame.wave, fxFrame.color, width, height);
                    }
                    drawPendoloBeatFxOverlay2d(ctx, frame, fxFrame);
                }
                ctx.restore();
            }

            animationFrameId = window.requestAnimationFrame(render);
        };

        const unsubscribeVisibility = subscribeAppForegroundVisibility((visible) => {
            if (!visible) {
                lastTimestampRef.current = null;
                if (animationFrameId) {
                    window.cancelAnimationFrame(animationFrameId);
                    animationFrameId = 0;
                }
            } else if (!animationFrameId) {
                animationFrameId = window.requestAnimationFrame(render);
            }
        });

        if (isAppForegroundVisible()) {
            animationFrameId = window.requestAnimationFrame(render);
        }

        return () => {
            unsubscribeVisibility();
            if (animationFrameId) window.cancelAnimationFrame(animationFrameId);
            webglCanvas?.removeEventListener('webglcontextlost', handleContextLost);
            webglCanvas?.removeEventListener('webglcontextrestored', handleContextRestored);
        };
    }, [showGearDecor, showCenterGradient, showCover, audioBassMotionValue, escapementAngleMotionValue, beatFxRef]);

    useEffect(() => () => {
        rendererRef.current?.release();
        rendererRef.current = null;
    }, []);

    if (showGearDecor === 'none' && !showCenterGradient && !showCover) {
        return null;
    }

    const canvasClass = 'absolute inset-0 w-full h-full pointer-events-none';
    const boxStyle: React.CSSProperties = {
        left: `${contentBox.left}px`,
        top: `${contentBox.top}px`,
        width: `${contentBox.width}px`,
        height: `${contentBox.height}px`,
        zIndex: 1,
    };
    // Same CSS glow on both backends so WebGL/Canvas2D luminance stays aligned.
    const lineGlow = enableLineGlow
        ? `drop-shadow(0 0 4px ${colorWithAlpha(accentTextColor, 0.65)}) drop-shadow(0 0 12px ${colorWithAlpha(accentTextColor, 0.3)})`
        : undefined;

    return (
        <div className="absolute pointer-events-none" style={boxStyle}>
            <canvas
                ref={webglCanvasRef}
                className={canvasClass}
                style={{ filter: lineGlow }}
                aria-hidden="true"
            />
            <canvas
                ref={canvas2dRef}
                className={canvasClass}
                style={{ visibility: 'hidden', filter: lineGlow }}
                aria-hidden="true"
            />
        </div>
    );
};

export default PendoloClockworkCanvas;

