// The requests a sign-in waits for. They get the sign-in's time limit.
const LOGIN_REQUESTS: ReadonlySet<QqOperation> = new Set(['login_qr_key', 'login_qr_create', 'login_qr_check']);
// The requests for a song's address and a collection's tracks. They get the limit below; no other
// request has a limit.
const ONLINE_REQUESTS: ReadonlySet<QqOperation> = new Set([
    'music_play', 'song_list_detail', 'user_playlist_detail', 'user_liked_songs', 'album_info',
    'user_cloud', 'recommend_toplist', 'radio_tracks',
]);
// Their limit, above the backend's own slowest answer. A signed-in play link is at worst four steps in a
// row (qq-music-api, services/auth/qrLogin.js): GetVkey, a 5 s CDN probe, GetCdnDispatch and a second
// 5 s probe, each call to QQ limited to 25 s (services/auth/httpClient.js): 60 s in all.
export const QQ_ONLINE_REQUEST_LIMIT_MS = 70_000;

// qq-music-api translates the native QR states into the Netease codes; 803 is the only one carrying a session.
const QR_CONFIRMED_CODE = 803;

const getWebApiBase = (): string => {
    const runtimeBase = getStoredRuntimeApiBase('qq');
    if (runtimeBase) return runtimeBase;
    const viteValue = typeof import.meta !== 'undefined' && import.meta.env?.MODE !== 'test'
        ? String((import.meta as ImportMeta & { env?: Record<string, string> }).env?.VITE_QQ_API_BASE || '')
        : '';
    const processValue = typeof process !== 'undefined'
        ? String(process.env?.VITE_QQ_API_BASE || '')
        : '';
    const value = viteValue || processValue;
    return value.trim().replace(/\/$/, '');
};

// Electron embeds qq-music-api and starts it on a free port, so the base is only known at runtime.
const getElectronQqPortReader = (): (() => Promise<number | null>) | null => {
    if (typeof window === 'undefined') return null;
    const reader = window.electron?.getQqPort;
    return typeof reader === 'function' ? () => reader() : null;
};

// What a request fails with where the desktop app's embedded backend has no port: the sentence
// starts with it, and goes on with the status the main process gives (`describeEmbeddedStatus`).
// The sign-in dialog tells this failure apart by it (qqLoginFailure.ts).
export const QQ_API_NOT_RUNNING = 'Embedded QQMusicApi is not running';

// What a request fails with where the web build has no backend address configured.
export const QQ_API_BASE_MISSING = 'VITE_QQ_API_BASE is not configured';

let electronApiBase: string | null = null;

export const resetQqTransportRuntimeCache = (): void => {
    electronApiBase = null;
};

// 内嵌后端没在监听时，把主进程报的状态与故障原因带进错误：时间线里直接能看到它为什么没起来。
const describeEmbeddedStatus = async (): Promise<string> => {
    try {
        const status = await window.electron?.getQqApiStatus?.();
        return status ? ` (status ${status.status}${status.error ? `: ${status.error}` : ''})` : '';
    } catch {
        return '';
    }
};

const resolveApiBase = async (): Promise<string> => {
    const readPort = getElectronQqPortReader();
    if (readPort) {
        if (electronApiBase) return electronApiBase;
        const port = await readPort();
        if (!port) {
            throw new OnlineProviderError('unavailable', `${QQ_API_NOT_RUNNING}${await describeEmbeddedStatus()}`, 'qq');
        }
        electronApiBase = `http://127.0.0.1:${port}`;
        return electronApiBase;
    }

    const base = getWebApiBase();
    if (!base) {
        // 网页版没配后端地址：这里用不了 QQ 音乐，再试也一样（qqFailure.ts 说它是「没有配置」）。
        throw new OnlineProviderError('unavailable', QQ_API_BASE_MISSING, 'qq');
    }
    return base;
};

// The stored value is the backend's opaque `qqmusic_session=<token>` string, never a QQ credential.
const getWebSessionCookie = (): string => readProviderSessionValue('qq', 'cookie') || '';

const SESSION_COOKIE_NAME = 'qqmusic_session';
const SESSION_HEADER_NAME = 'X-QQ-Session';

// 后端两个入口的语义不同，不能互换：header 收的是裸 token，`?cookie=` 收的是整串 cookie。
const tokenFromCookieString = (cookie: string): string => {
    for (const entry of cookie.split(';')) {
        const separator = entry.indexOf('=');
        if (separator <= 0) continue;
        if (entry.slice(0, separator).trim() === SESSION_COOKIE_NAME) return entry.slice(separator + 1).trim();
    }
    return '';
};

// 同源部署（`/api/qq`、`/qq`）改走 header：sealed token 是密文本身，query 是它唯一会被 CDN 与
// edge access log 完整记下来的地方 —— 那是 sealed 相对不透明 token 唯一真正新增的泄漏面。
// 外部 URL 与 Electron 维持 `?cookie=`：跨源发自定义头会触发 preflight，而后端是
// `Access-Control-Allow-Origin: *`，按规范不允许搭配 credentials。
const isSameOriginBase = (base: string): boolean => base.startsWith('/');

export const hasQqSession = (): boolean => Boolean(getWebSessionCookie());

export const clearQqSession = (): void => removeProviderSessionValue('qq', 'cookie');

// 后端的退避时长（qq-music-api 在 429 的响应体里给 retryAfterMs，同时带 Retry-After 头，单位是秒）。
// 只收非负安全整数，读不出就不给，调用方按普通失败处理。
const readRetryAfterMs = (body: unknown, response: Response): number | undefined => {
    const fromBody = body && typeof body === 'object' ? (body as { retryAfterMs?: unknown }).retryAfterMs : undefined;
    if (typeof fromBody === 'number' && Number.isSafeInteger(fromBody) && fromBody >= 0) return fromBody;
    const raw = response.headers?.get?.('Retry-After')?.trim();
    if (!raw || !/^\d+$/.test(raw)) return undefined;
    const seconds = Number(raw);
    return Number.isSafeInteger(seconds * 1000) ? seconds * 1000 : undefined;
};

const readJsonBody = async (response: Response): Promise<any> => {
    try {
        return await response.json();
    } catch {
        return undefined;
    }
};

// 后端失败正文的原文：多数路由写在 `message`，播放等路由的 500 只给 `{ error }`（observability.js），两处都认。
// 3.2.0 起的新路由另带固定的 `errorKey`（如 `playlist.already-applied`）与可选的上游数字码，`message` 只是通用英文，
// 所以把这两样一起写进原文，诊断里才看得出是哪一类失败。
export const readBackendMessage = (failure: any): string => {
    let text = '';
    for (const candidate of [failure?.message, failure?.error]) {
        if (typeof candidate === 'string' && candidate.trim()) {
            text = candidate.trim();
            break;
        }
    }
    const errorKey = typeof failure?.errorKey === 'string' ? failure.errorKey.trim() : '';
    const upstreamCode = Number.isSafeInteger(failure?.upstreamCode) ? ` upstream ${failure.upstreamCode}` : '';
    if (!errorKey) return text;
    return `${errorKey}${upstreamCode}${text ? `: ${text}` : ''}`;
};

// qq-music-api 的 QqProtocolError 模板（dist/src/services/auth/qrLogin.js 的 callMusicu）：musicu 已经应答（HTTP 2xx），
// 只是带了非零的全局码或 req_0 码，后端的 handleControllerError 一律把它包成 500 `{ error }`。
const QQ_PROTOCOL_REFUSAL = /\bfailed \(HTTP 2\d\d, global=(-?\d+), code=(-?\d+|unknown)\)/;

// 从 500 正文里认出「上游有应答、只是业务拒绝」，返回上游码：req_0 的码优先，缺失时退回全局码，
// 两者都没有（应答里没有 req_0）记作 'missing'。认不出就返回 undefined，按普通 5xx 处理。
export const readUpstreamRefusalCode = (backendText: string): number | string | undefined => {
    const match = QQ_PROTOCOL_REFUSAL.exec(backendText);
    if (!match) return undefined;
    const [, globalCode, requestCode] = match;
    if (requestCode !== 'unknown' && Number(requestCode) !== 0) return Number(requestCode);
    if (Number(globalCode) !== 0) return Number(globalCode);
    return 'missing';
};

// 曲库三条路由被上游拒收时仍然回 HTTP 200，状态码藏在响应体里，而且层级还不一样：
// `/getAlbumInfo` 直接是 `response.code`（参数类型错时是 1101 `para error!`），
// 两条歌手路由的 `response.code` 恒为 0，真正的状态在 `response.singer.code`（400 / 104400）。
// 不看这两层就会把「被拒收」当成「这个专辑没有曲目」，UI 只剩一片空白，线上很难定位。
// 登录与播放路由用的是另一套码值（如 `login_status` 回 200），故不纳入此检查。
const CATALOG_STATUS_NODES: Partial<Record<QqOperation, string[][]>> = {
    album_info: [['response']],
    // 歌单详情的上游是匿名 CGI：歌单不存在、不公开或参数不被接受时它照样回 HTTP 200，
    // 差别只在这个 `code` 上。不登记的话拒绝会一路变成空歌单，UI 只剩「暂无内容」。
    song_list_detail: [['response']],
    artist_songs: [['response'], ['response', 'singer']],
    artist_albums: [['response'], ['response', 'singer']],
};

const readNode = (body: any, path: string[]): any => (
    path.reduce((node, key) => (node === null || node === undefined ? node : node[key]), body)
);

const assertUpstreamAccepted = (operation: QqOperation, body: any): void => {
    for (const path of CATALOG_STATUS_NODES[operation] ?? []) {
        const node = readNode(body, path);
        const code = Number(node?.code);
        if (!Number.isFinite(code) || code === 0) continue;

        const subcode = Number(node?.subcode);
        const message = typeof node?.message === 'string' ? node.message.trim() : '';
        throw new OnlineProviderError(
            'invalid-response',
            `QQMusicApi ${operation} was rejected upstream at ${path.join('.')} (code ${code}`
            + `${Number.isFinite(subcode) && subcode !== code ? `, subcode ${subcode}` : ''})`
            + `${message ? `: ${message}` : ''}`,
            'qq',
            node,
        );
    }
};

const persistConfirmedSession = (operation: QqOperation, body: any): void => {
    if (operation !== 'login_qr_check' || Number(body?.code) !== QR_CONFIRMED_CODE) return;
    const cookie = body?.cookie;
    if (typeof cookie === 'string' && cookie) writeProviderSessionValue('qq', 'cookie', cookie);
};

/** 网页版配置的远端 API 地址（自检与诊断报告用）；桌面版走内嵌后端，返回 null。 */
export const getQqRemoteApiBase = (): string | null => (getElectronQqPortReader() ? null : getWebApiBase() || null);

export const getQqTransportAvailability = () => {
    if (getElectronQqPortReader()) return { configured: true } as const;
    return getWebApiBase()
        ? { configured: true } as const
        : { configured: false, reason: 'not-configured' as const };
};

const endpointFor = (operation: QqOperation, params: QqParams): { path: string; query: QqParams } => {
    const query = { ...params };
    const takeRequiredPathParam = (name: string): string => {
        const value = query[name];
        delete query[name];
        const pathValue = value === undefined ? '' : String(value).trim();
        if (!pathValue) {
            throw new OnlineProviderError(
                'invalid-response',
                `QQMusicApi ${operation} requires ${name}`,
                'qq',
            );
        }
        return encodeURIComponent(pathValue);
    };

    if (operation === 'music_play') {
        return { path: `${ENDPOINTS[operation]}/${takeRequiredPathParam('songmid')}`, query };
    }
    if (operation === 'song_list_detail') {
        return { path: `${ENDPOINTS[operation]}/${takeRequiredPathParam('disstid')}`, query };
    }
    if (operation === 'song_info') {
        const songmid = takeRequiredPathParam('songmid');
        const songid = query.songid;
        delete query.songid;
        return {
            path: `${ENDPOINTS[operation]}/${songmid}${songid === undefined ? '' : `/${encodeURIComponent(String(songid))}`}`,
            query,
        };
    }
    return { path: ENDPOINTS[operation], query };
};

// The session a request carried is dropped; one that was stored since stays.
const dropSessionSent = (sent: string): void => {
    if (getWebSessionCookie() === sent) clearQqSession();
};

// Routes one provider request through the embedded Electron server or the configured Web base URL.
// It carries the session as the page keeps it when the request is made, before the first wait.
// 写入路由（POST_OPERATIONS）的参数放在 JSON 正文 `payload` 里；会话照旧走 header 或 `?cookie=`，后端两条路由都认。
export const requestQq = async <T = unknown>(
    operation: QqOperation,
    params: QqParams = {},
    payload?: Record<string, unknown>,
): Promise<T> => {
    const isPost = POST_OPERATIONS.has(operation);
    if (isPost !== (payload !== undefined)) {
        throw new OnlineProviderError(
            'invalid-response',
            `QQMusicApi ${operation} ${isPost ? 'requires' : 'does not take'} a request body`,
            'qq',
        );
    }
    const cookie = getWebSessionCookie();
    const base = await resolveApiBase();

    const endpoint = endpointFor(operation, params);
    const query = new URLSearchParams();
    Object.entries(endpoint.query).forEach(([key, value]) => {
        if (value !== undefined) query.set(key, String(value));
    });
    const headers: Record<string, string> = {};
    if (cookie) {
        if (isSameOriginBase(base)) {
            const token = tokenFromCookieString(cookie);
            // 同源请求不允许把未知格式的 session 放回 URL；清掉无效值，交给后端按未登录处理。
            if (token) headers[SESSION_HEADER_NAME] = token;
            else dropSessionSent(cookie);
        } else {
            query.set('cookie', cookie);
        }
    }
    query.set('timestamp', String(Date.now()));

    // Same-origin serverless calls must retain deployment-protection cookies; external qq-music-api instances
    // answer with `Access-Control-Allow-Origin: *`, so those requests still omit browser credentials.
    const credentials: RequestCredentials = isSameOriginBase(base) ? 'same-origin' : 'omit';
    const init: RequestInit = isPost
        ? { method: 'POST', credentials, headers: { ...headers, 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }
        : { credentials, headers };
    // The answer and its body, read together: the time limit covers both.
    const send = async (signal?: AbortSignal) => {
        const answer = await fetch(`${base}${endpoint.path}?${query}`, { ...init, ...(signal ? { signal } : {}) });
        return { response: answer, body: await readJsonBody(answer) };
    };
    const { response, body } = await (LOGIN_REQUESTS.has(operation) ? withLoginRequestLimit(send)
        : ONLINE_REQUESTS.has(operation) ? withOnlineRequestLimit(send, QQ_ONLINE_REQUEST_LIMIT_MS) : send());
    if (!response.ok) {
        // A missing, expired, rejected, or non-persisted backend session is surfaced uniformly as 401.
        if (response.status === 401) {
            dropSessionSent(cookie);
            throw new OnlineProviderError('auth-required', 'QQMusicApi login required', 'qq', body, response.status);
        }
        // 404 是「这个后端没有这条路由」，不是网络故障 —— 用户可以自行部署任意版本的后端，
        // 新路由在旧后端上必然 404。报成 `unsupported`，调用方才能据此回落到旧路径，
        // 而不必去解析错误文案里的状态码。
        if (response.status === 404) {
            throw new OnlineProviderError(
                'unsupported',
                `QQMusicApi has no ${operation} route`,
                'qq',
                body,
                response.status,
            );
        }
        // The status is in the sentence, the backend's answer in the cause (qqFailure.ts reads both), and the wait a
        // 429 asks for on the error.
        throw new OnlineProviderError('network', `QQMusicApi request failed: ${response.status}`, 'qq', body, response.status, readRetryAfterMs(body, response));
    }

    if (body === undefined) {
        throw new OnlineProviderError('invalid-response', `QQMusicApi returned an unreadable ${operation} body`, 'qq');
    }
    assertUpstreamAccepted(operation, body);
    persistConfirmedSession(operation, body);
    return body as T;
};

src/services/onlineMusic/runtimeApiConfi:
// src/services/onlineMusic/runtimeApiConfig.ts
// Manages runtime-configurable online provider API base URLs (persisted in localStorage)
// and provides honest capability/availability diagnostics and offline-to-online transition monitoring.

export type ConfigurableOnlineProviderId = 'netease' | 'qq' | 'kugou';

export const RUNTIME_API_BASE_STORAGE_KEYS: Record<ConfigurableOnlineProviderId, string> = {
    netease: 'folia_netease_api_base',
    qq: 'folia_qq_api_base',
    kugou: 'folia_kugou_api_base',
};

export const RUNTIME_API_CHANGED_EVENT = 'folia:runtime-api-config-changed';

const sanitizeBaseUrl = (value: unknown): string => {
    if (typeof value !== 'string') return '';
    const trimmed = value.trim().replace(/\/+$/, '');
    if (!trimmed) return '';
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || trimmed.startsWith('/')) {
        return trimmed;
    }
    return `https://${trimmed}`;
};

export const getStoredRuntimeApiBase = (providerId: ConfigurableOnlineProviderId): string => {
    try {
        if (typeof localStorage === 'undefined' || typeof localStorage.getItem !== 'function') {
            return '';
        }
        return sanitizeBaseUrl(localStorage.getItem(RUNTIME_API_BASE_STORAGE_KEYS[providerId]));
    } catch {
        return '';
    }
};

export const setStoredRuntimeApiBase = (providerId: ConfigurableOnlineProviderId, url: string): string => {
    const clean = sanitizeBaseUrl(url);
    try {
        if (typeof localStorage !== 'undefined') {
            if (clean) {
                localStorage.setItem(RUNTIME_API_BASE_STORAGE_KEYS[providerId], clean);
            } else {
                localStorage.removeItem(RUNTIME_API_BASE_STORAGE_KEYS[providerId]);
            }
        }
        if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
            window.dispatchEvent(new CustomEvent(RUNTIME_API_CHANGED_EVENT, { detail: { providerId, url: clean } }));
        }
    } catch {
        // Ignore storage errors
    }
    return clean;
};

export const getEnvApiBase = (providerId: ConfigurableOnlineProviderId): string => {
    const envKey = providerId === 'netease'
        ? 'VITE_NETEASE_API_BASE'
        : providerId === 'qq'
            ? 'VITE_QQ_API_BASE'
            : 'VITE_KUGOU_API_BASE';

    const viteEnv = typeof import.meta !== 'undefined' ? (import.meta as unknown as { env?: Record<string, unknown> }).env : undefined;
    if (viteEnv && viteEnv.MODE !== 'test' && typeof viteEnv[envKey] === 'string' && viteEnv[envKey]) {
        return sanitizeBaseUrl(viteEnv[envKey]);
    }
    if (typeof process !== 'undefined' && process.env && typeof process.env[envKey] === 'string' && process.env[envKey]) {
        return sanitizeBaseUrl(process.env[envKey]);
    }
    return '';
};

export const resolveProviderWebApiBase = (providerId: ConfigurableOnlineProviderId): string => {
    return getStoredRuntimeApiBase(providerId) || getEnvApiBase(providerId);
};

export const isElectronBridgeAvailable = (): boolean => (
    typeof window !== 'undefined' && Boolean((window as Window & { electron?: unknown }).electron)
);

export type OnlineServiceAvailabilityKind =
    | 'ready'
    | 'offline'
    | 'needs_api_base'
    | 'needs_desktop_bridge'
    | 'needs_navidrome_config';

export interface OnlineServiceDiagnostic {
    id: string;
    label: string;
    availability: OnlineServiceAvailabilityKind;
    endpointUrl: string | null;
    canConfigureEndpoint: boolean;
    summary: string;
    detail: string;
}

export const getIsDeviceOnline = (): boolean => {
    if (typeof navigator === 'undefined' || typeof navigator.onLine !== 'boolean') {
        return true;
    }
    return navigator.onLine;
};

export const subscribeDeviceOnlineStatus = (listener: (online: boolean) => void): (() => void) => {
    if (typeof window === 'undefined' || typeof window.addEventListener !== 'function') {
        return () => {};
    }
    const onOnline = () => listener(true);
    const onOffline = () => listener(false);
    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);
    return () => {
        window.removeEventListener('online', onOnline);
        window.removeEventListener('offline', onOffline);
    };
};

export const getOnlineProviderDiagnostic = (providerId: string): OnlineServiceDiagnostic => {
    const online = getIsDeviceOnline();
    const isElectron = isElectronBridgeAvailable();

    if (providerId === 'amll-db') {
        return {
            id: 'amll-db',
            label: 'AMLL TTML Lyrics DB',
            availability: online ? 'ready' : 'offline',
            endpointUrl: 'https://api.amll.dev',
            canConfigureEndpoint: false,
            summary: online ? 'Direct CORS TTML lyrics search & download ready' : 'Device is offline',
            detail: online
                ? 'Connects directly to https://api.amll.dev for word/syllable-timed TTML lyrics without requiring a custom proxy.'
                : 'Reconnect to the internet to search AMLL TTML lyrics. Locally stored and cached lyrics remain available offline.',
        };
    }

    if (providerId === 'netease' || providerId === 'qq' || providerId === 'kugou') {
        const label = providerId === 'netease'
            ? 'NetEase Cloud Music (网易云音乐)'
            : providerId === 'qq'
                ? 'QQ Music (QQ音乐)'
                : 'KuGou Music (酷狗音乐)';
        const base = isElectron ? 'http://127.0.0.1 (Embedded Electron Worker)' : resolveProviderWebApiBase(providerId);
        if (!online) {
            return {
                id: providerId,
                label,
                availability: 'offline',
                endpointUrl: base || null,
                canConfigureEndpoint: !isElectron,
                summary: 'Offline — network connection required',
                detail: 'Online search, playlists, and streaming for this provider require an active internet connection.',
            };
        }
        if (!base) {
            const envName = providerId === 'netease'
                ? 'VITE_NETEASE_API_BASE'
                : providerId === 'qq'
                    ? 'VITE_QQ_API_BASE'
                    : 'VITE_KUGOU_API_BASE';
            return {
                id: providerId,
                label,
                availability: 'needs_api_base',
                endpointUrl: null,
                canConfigureEndpoint: true,
                summary: 'API backend URL required on Android / Web',
                detail: `${label} requires a deployed API gateway URL (${envName} or configured in Backends below) to proxy requests and sign parameters.`,
            };
        }
        return {
            id: providerId,
            label,
            availability: 'ready',
            endpointUrl: base,
            canConfigureEndpoint: !isElectron,
            summary: `Configured (${base})`,
            detail: `Using API endpoint ${base} for search, playlists, discovery, and account sessions.`,
        };
    }

    if (providerId === 'bodian' || providerId === 'ytm' || providerId === 'spotify') {
        const label = providerId === 'bodian'
            ? 'BoDian Music (波点音乐)'
            : providerId === 'ytm'
                ? 'YouTube Music'
                : 'Spotify';
        if (isElectron) {
            return {
                id: providerId,
                label,
                availability: online ? 'ready' : 'offline',
                endpointUrl: 'electron://ipc-bridge',
                canConfigureEndpoint: false,
                summary: online ? 'Desktop IPC bridge active' : 'Offline',
                detail: 'Connected via Electron main-process native bridge.',
            };
        }
        const reason = providerId === 'spotify'
            ? 'Spotify playback in Folia relies on the native Node module @lox-audioserver/node-librespot and Electron main-process IPC (electron/spotify/spotifyApiBridge.cjs), which cannot run inside an Android WebView.'
            : providerId === 'ytm'
                ? 'YouTube Music in Folia relies on the Electron main-process InnerTube + BotGuard poToken sandbox bridge (electron/ytm/ytmApiBridge.cjs), which is desktop-only.'
                : 'BoDian Music in Folia relies on the Electron main-process IPC bridge (electron/bodian/bodianApiBridge.cjs) and is desktop-only.';
        return {
            id: providerId,
            label,
            availability: 'needs_desktop_bridge',
            endpointUrl: null,
            canConfigureEndpoint: false,
            summary: 'Desktop Electron runtime required',
            detail: reason,
        };
    }

    return {
        id: providerId,
        label: providerId,
        availability: online ? 'ready' : 'offline',
        endpointUrl: null,
        canConfigureEndpoint: false,
        summary: online ? 'Available' : 'Offline',
        detail: '',
    };
};

import type { DualTheme, LocalSong, LyricData } from '../types';
import type { LocalLibraryAssignment, LocalLibraryEntity } from '../types/localLibrary';
import type { RawLyricSource } from '../utils/lyrics/types';
import { ensureLyricDataRenderHints } from '../utils/lyrics/renderHints';
import {
    cacheAndroidCoverAndExtractPalette,
    deleteAndroidDiskCacheEntry,
    readAndroidDiskCacheJson,
    writeAndroidDiskCacheJson,
    type FoliaDiskCacheNamespace,
} from './android/foliaAndroidBridge';

// src/services/persistentDiskCacheService.ts
// Persistent internal disk cache coordinator backed by Android's context.getFilesDir()/media_cache/
// (with an in-memory hot tier for synchronous/zero-latency hits and test environments):
//   1. Pre-Parsed & Pre-Segmented Lyrics (media_cache/lyrics/): full LyricData timeline, word/syllable
//      timing structures, Jieba/ICU autoWordSegments, Pinyin/romanization, and translation rows, plus
//      song-keyed offline saved online lyrics (TTML, QRC, YRC, KRC, LRC, VTT) for 100% offline playback.
//   2. Cover Art Mipmaps & Theme Palettes (media_cache/covers/ & media_cache/palettes/): 256x256 WebP
//      (for grids/Bravais lattice walls), 1024x1024 WebP (for the player), vibrant/representative
//      hex color palettes, and Monet/dynamic DualTheme palettes.
//   3. Persistent Library Index (media_cache/index/): scanned SAF library metadata index for instant launch.

export interface CachedCoverPaletteRecord {
    assetId: string;
    vibrantColors?: string[];
    representativeColors?: string[];
    dualTheme?: DualTheme;
    updatedAt: number;
}

export interface PersistedLibraryIndexSnapshot {
    version: number;
    updatedAt: number;
    songs: LocalSong[];
    entities?: LocalLibraryEntity[];
    assignments?: LocalLibraryAssignment[];
}

const LIBRARY_INDEX_CACHE_KEY = 'library_index_v1';
const LIBRARY_INDEX_SCHEMA_VERSION = 1;
const MAX_MEMORY_LYRIC_ENTRIES = 300;
const MAX_MEMORY_PALETTE_ENTRIES = 500;

const memoryLyricsCache = new Map<string, LyricData>();
const memoryPaletteCache = new Map<string, CachedCoverPaletteRecord>();
let memoryLibraryIndex: PersistedLibraryIndexSnapshot | null = null;

// Weak reference map from a parsed LyricData object (or its line content digest) to its disk cache key
// so post-parse segmentation (Jieba/ICU autoWordSegments, chorus detection, renderHints) can write back
// the ready-to-render structure to the exact same disk cache entry.
const lyricDataToCacheKey = new WeakMap<LyricData, string>();
const contentDigestToCacheKey = new Map<string, string>();

const fnv1a64Hex = (input: string): string => {
    let h1 = 0xdeadbeef ^ input.length;
    let h2 = 0x41c6ce57 ^ input.length;
    for (let i = 0; i < input.length; i += 1) {
        const ch = input.charCodeAt(i);
        h1 = Math.imul(h1 ^ ch, 2654435761);
        h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return `${(h1 >>> 0).toString(16).padStart(8, '0')}${(h2 >>> 0).toString(16).padStart(8, '0')}`;
};

export const computeParsedLyricsContentDigest = (lyrics: LyricData | null | undefined): string | null => {
    if (!lyrics || !Array.isArray(lyrics.lines) || lyrics.lines.length === 0) return null;
    const count = lyrics.lines.length;
    const first = lyrics.lines[0];
    const mid = lyrics.lines[Math.floor(count / 2)];
    const last = lyrics.lines[count - 1];
    const signature = [
        count,
        Boolean(lyrics.isWordByWord),
        first?.startTime ?? 0,
        first?.fullText ?? '',
        first?.translation ?? '',
        mid?.startTime ?? 0,
        mid?.fullText ?? '',
        last?.startTime ?? 0,
        last?.fullText ?? '',
    ].join('|');
    return `ld_${fnv1a64Hex(signature)}`;
};

export const computeLyricSourceCacheKey = (source: RawLyricSource, optionsSignature = ''): string => {
    const rec = source as unknown as Record<string, unknown>;
    const str = (key: string, altKey?: string): string => {
        const val = rec[key] ?? (altKey ? rec[altKey] : undefined);
        return typeof val === 'string' ? val : '';
    };
    let rawPayload = '';
    switch (source.type) {
        case 'embedded':
            rawPayload = `embedded|${str('textContent')}|${str('translationContent')}`;
            break;
        case 'local':
            rawPayload = `local|${str('formatHint')}|${str('lrcContent')}|${str('tLrcContent')}|${str('yrcContent')}`;
            break;
        case 'qrc':
            rawPayload = `qrc|${str('qrc', 'qrcContent')}|${str('tLrc', 'tlrc')}|${str('romaLrc', 'romalrc')}`;
            break;
        case 'navidrome':
            rawPayload = `navidrome|${JSON.stringify(rec.structured ?? rec.lines ?? null)}|${str('rawText', 'lrcContent')}`;
            break;
        default:
            rawPayload = (rec.lrc !== undefined || rec.yrc !== undefined || rec.ttml !== undefined)
                ? `${String(rec.type ?? '')}|${str('lrc')}|${str('tLrc', 'tlrc')}|${str('yrc')}|${str('romaLrc', 'romalrc')}|${str('ttml')}`
                : JSON.stringify(source);
            break;
    }
    return `lyric_v1_${fnv1a64Hex(`${optionsSignature}|${rawPayload}`)}_${rawPayload.length}`;
};

const touchMemoryLyricCache = (key: string, value: LyricData): void => {
    memoryLyricsCache.delete(key);
    memoryLyricsCache.set(key, value);
    while (memoryLyricsCache.size > MAX_MEMORY_LYRIC_ENTRIES) {
        const oldest = memoryLyricsCache.keys().next().value;
        if (!oldest) break;
        memoryLyricsCache.delete(oldest);
    }
};

export const associateLyricDataWithCacheKey = (lyrics: LyricData | null | undefined, cacheKey: string): void => {
    if (!lyrics || !cacheKey) return;
    lyricDataToCacheKey.set(lyrics, cacheKey);
    const digest = computeParsedLyricsContentDigest(lyrics);
    if (digest) {
        contentDigestToCacheKey.set(digest, cacheKey);
    }
};

export const readPreParsedLyricsFromDisk = async (cacheKey: string): Promise<LyricData | null> => {
    if (!cacheKey) return null;
    const memHit = memoryLyricsCache.get(cacheKey);
    if (memHit) {
        touchMemoryLyricCache(cacheKey, memHit);
        associateLyricDataWithCacheKey(memHit, cacheKey);
        return memHit;
    }

    const rawJson = await readAndroidDiskCacheJson('lyrics', cacheKey);
    if (!rawJson) return null;
    try {
        const parsed = JSON.parse(rawJson) as LyricData;
        if (!parsed || !Array.isArray(parsed.lines)) return null;
        const hydrated = ensureLyricDataRenderHints(parsed) ?? parsed;
        touchMemoryLyricCache(cacheKey, hydrated);
        associateLyricDataWithCacheKey(hydrated, cacheKey);
        return hydrated;
    } catch {
        return null;
    }
};

export const writePreParsedLyricsToDisk = async (
    cacheKey: string,
    lyrics: LyricData | null | undefined,
): Promise<void> => {
    if (!cacheKey || !lyrics || !Array.isArray(lyrics.lines) || lyrics.lines.length === 0) return;
    const normalized = ensureLyricDataRenderHints(lyrics) ?? lyrics;
    touchMemoryLyricCache(cacheKey, normalized);
    associateLyricDataWithCacheKey(normalized, cacheKey);
    try {
        await writeAndroidDiskCacheJson('lyrics', cacheKey, JSON.stringify(normalized));
    } catch {
        // Ignore disk write failure.
    }
};

/**
 * Permanently saves online-fetched lyrics (TTML, QRC, YRC, KRC, LRC, VTT) keyed by both
 * songId and fileSignature in context.getFilesDir()/media_cache/lyrics/ so they are always
 * available for offline playback even if the song record is re-hydrated or played without internet.
 */
export const writeOfflineSavedLyricsForSong = async (
    songId: string | undefined | null,
    fileSignature: string | undefined | null,
    lyrics: LyricData | null | undefined,
): Promise<void> => {
    if (!lyrics || !Array.isArray(lyrics.lines) || lyrics.lines.length === 0) return;
    const tasks: Promise<void>[] = [];
    if (songId && songId.trim()) {
        tasks.push(writePreParsedLyricsToDisk(`offline_song_${fnv1a64Hex(songId.trim())}`, lyrics));
    }
    if (fileSignature && fileSignature.trim()) {
        tasks.push(writePreParsedLyricsToDisk(`offline_sig_${fnv1a64Hex(fileSignature.trim())}`, lyrics));
    }
    const digest = computeParsedLyricsContentDigest(lyrics);
    if (digest) {
        tasks.push(writePreParsedLyricsToDisk(`matched_${digest}`, lyrics));
    }
    await Promise.all(tasks);
};

export const readOfflineSavedLyricsForSong = async (
    songId: string | undefined | null,
    fileSignature?: string | null,
): Promise<LyricData | null> => {
    if (songId && songId.trim()) {
        const byId = await readPreParsedLyricsFromDisk(`offline_song_${fnv1a64Hex(songId.trim())}`);
        if (byId && Array.isArray(byId.lines) && byId.lines.length > 0) {
            return byId;
        }
    }
    if (fileSignature && fileSignature.trim()) {
        const bySig = await readPreParsedLyricsFromDisk(`offline_sig_${fnv1a64Hex(fileSignature.trim())}`);
        if (bySig && Array.isArray(bySig.lines) && bySig.lines.length > 0) {
            return bySig;
        }
    }
    return null;
};

/**
 * Persists a fully post-processed LyricData structure (with Jieba/ICU autoWordSegments,
 * chorus markers, Pinyin/romanization, translations, and renderHints) to the persistent
 * disk cache so subsequent plays of the same track skip both parsing and word segmentation.
 */
const preSegmentedLyricSet = new WeakSet<LyricData>();

export const isPreSegmentedLyricsReady = (lyrics: LyricData | null | undefined): boolean => {
    if (!lyrics || !Array.isArray(lyrics.lines) || lyrics.lines.length === 0) return false;
    if (preSegmentedLyricSet.has(lyrics)) return true;
    return lyrics.lines.some(
        line => (Array.isArray(line.autoWordSegments) && line.autoWordSegments.length > 0) || typeof line.isChorus === 'boolean',
    );
};

export const persistPreSegmentedLyricsToDisk = (
    lyrics: LyricData | null | undefined,
    songKey?: string | number | null,
): void => {
    if (!lyrics || !Array.isArray(lyrics.lines) || lyrics.lines.length === 0) return;
    const normalized = ensureLyricDataRenderHints(lyrics) ?? lyrics;
    preSegmentedLyricSet.add(lyrics);
    preSegmentedLyricSet.add(normalized);
    const directKey = lyricDataToCacheKey.get(lyrics) || lyricDataToCacheKey.get(normalized);
    const digest = computeParsedLyricsContentDigest(normalized);
    const resolvedCacheKey = directKey || (digest ? contentDigestToCacheKey.get(digest) : undefined);

    if (resolvedCacheKey) {
        lyricDataToCacheKey.set(normalized, resolvedCacheKey);
        void writePreParsedLyricsToDisk(resolvedCacheKey, normalized);
    }
    if (songKey !== undefined && songKey !== null && String(songKey).trim().length > 0) {
        const songCacheKey = `song_lyric_v1_${fnv1a64Hex(String(songKey))}`;
        void writePreParsedLyricsToDisk(songCacheKey, normalized);
    }
};

export const readSongPreSegmentedLyricsFromDisk = async (
    songKey: string | number | null | undefined,
): Promise<LyricData | null> => {
    if (songKey === undefined || songKey === null || String(songKey).trim().length === 0) return null;
    const songCacheKey = `song_lyric_v1_${fnv1a64Hex(String(songKey))}`;
    return await readPreParsedLyricsFromDisk(songCacheKey);
};

// ============================================================================
// Cover Art Mipmaps (256x256 & 1024x1024 WebP) & Theme Palette Disk Cache
// ============================================================================

const SHA256_EXTRACT_REGEX = /sha256(?::|%3A)([0-9a-f]{64})/i;

export const normalizePaletteCacheKey = (urlOrAssetId: string | null | undefined): string | null => {
    if (!urlOrAssetId || typeof urlOrAssetId !== 'string') return null;
    const trimmed = urlOrAssetId.trim();
    if (!trimmed) return null;
    const shaMatch = SHA256_EXTRACT_REGEX.exec(trimmed);
    if (shaMatch?.[1]) {
        return `sha256:${shaMatch[1].toLowerCase()}`;
    }
    if (/^[0-9a-f]{64}$/i.test(trimmed)) {
        return `sha256:${trimmed.toLowerCase()}`;
    }
    return `url_${fnv1a64Hex(trimmed)}`;
};

const toDiskPaletteFileKey = (normalizedKey: string): string => (
    normalizedKey.startsWith('sha256:') ? normalizedKey.slice('sha256:'.length) : normalizedKey
);

const touchMemoryPaletteCache = (key: string, record: CachedCoverPaletteRecord): void => {
    memoryPaletteCache.delete(key);
    memoryPaletteCache.set(key, record);
    while (memoryPaletteCache.size > MAX_MEMORY_PALETTE_ENTRIES) {
        const oldest = memoryPaletteCache.keys().next().value;
        if (!oldest) break;
        memoryPaletteCache.delete(oldest);
    }
};

export const stageCachedCoverPalette = (
    urlOrAssetId: string | null | undefined,
    patch: {
        vibrantColors?: string[];
        representativeColors?: string[];
        dualTheme?: DualTheme;
    },
): CachedCoverPaletteRecord | null => {
    const key = normalizePaletteCacheKey(urlOrAssetId);
    if (!key) return null;
    const existing = memoryPaletteCache.get(key);
    const merged: CachedCoverPaletteRecord = {
        assetId: key,
        vibrantColors: patch.vibrantColors?.length ? patch.vibrantColors : existing?.vibrantColors,
        representativeColors: patch.representativeColors?.length ? patch.representativeColors : existing?.representativeColors,
        dualTheme: patch.dualTheme ?? existing?.dualTheme,
        updatedAt: Date.now(),
    };
    touchMemoryPaletteCache(key, merged);
    return merged;
};

export const readCachedCoverPalette = async (
    urlOrAssetId: string | null | undefined,
): Promise<CachedCoverPaletteRecord | null> => {
    const key = normalizePaletteCacheKey(urlOrAssetId);
    if (!key) return null;

    const memHit = memoryPaletteCache.get(key);
    if (memHit) {
        touchMemoryPaletteCache(key, memHit);
        return memHit;
    }

    const diskKey = toDiskPaletteFileKey(key);
    const rawJson = await readAndroidDiskCacheJson('palettes', diskKey);
    if (!rawJson) return null;
    try {
        const parsed = JSON.parse(rawJson) as Partial<CachedCoverPaletteRecord>;
        if (!parsed || typeof parsed !== 'object') return null;
        const record: CachedCoverPaletteRecord = {
            assetId: key,
            vibrantColors: Array.isArray(parsed.vibrantColors) ? parsed.vibrantColors : undefined,
            representativeColors: Array.isArray(parsed.representativeColors) ? parsed.representativeColors : undefined,
            dualTheme: parsed.dualTheme,
            updatedAt: Number(parsed.updatedAt) || Date.now(),
        };
        touchMemoryPaletteCache(key, record);
        return record;
    } catch {
        return null;
    }
};

export const writeCachedCoverPalette = async (
    urlOrAssetId: string | null | undefined,
    patch: {
        vibrantColors?: string[];
        representativeColors?: string[];
        dualTheme?: DualTheme;
    },
): Promise<void> => {
    const key = normalizePaletteCacheKey(urlOrAssetId);
    if (!key) return;
    // Merge with any existing disk record first if not in memory yet
    if (!memoryPaletteCache.has(key)) {
        await readCachedCoverPalette(key);
    }
    const merged = stageCachedCoverPalette(key, patch);
    if (!merged) return;
    const diskKey = toDiskPaletteFileKey(key);
    try {
        await writeAndroidDiskCacheJson('palettes', diskKey, JSON.stringify(merged));
    } catch {
        // Ignore disk write failure.
    }
};

/**
 * Ensures 256x256 WebP (grids/Bravais lattice walls) and 1024x1024 WebP (player) mipmaps exist
 * in context.getFilesDir()/media_cache/covers/ and extracts/caches vibrant & representative
 * color palettes in context.getFilesDir()/media_cache/palettes/.
 */
export const ensureCoverMipmapsAndPalettePersisted = async (
    assetId: string,
    blob?: Blob,
    options?: {
        trackId?: string;
        albumId?: string;
        contentUri?: string;
    },
): Promise<CachedCoverPaletteRecord | null> => {
    const key = normalizePaletteCacheKey(assetId);
    if (!key) return null;
    const res = await cacheAndroidCoverAndExtractPalette({
        assetId: key,
        trackId: options?.trackId,
        albumId: options?.albumId,
        contentUri: options?.contentUri,
        blob,
    });
    if (res?.ok && (res.vibrantColors?.length || res.representativeColors?.length)) {
        return stageCachedCoverPalette(key, {
            vibrantColors: res.vibrantColors,
            representativeColors: res.representativeColors,
        });
    }
    return memoryPaletteCache.get(key) ?? null;
};

// ============================================================================
// Persistent Library Index (media_cache/index/library_index_v1.json)
// ============================================================================

export const readPersistedLibraryIndex = async (): Promise<PersistedLibraryIndexSnapshot | null> => {
    if (memoryLibraryIndex && memoryLibraryIndex.songs.length > 0) {
        return memoryLibraryIndex;
    }
    const rawJson = await readAndroidDiskCacheJson('index', LIBRARY_INDEX_CACHE_KEY);
    if (!rawJson) return null;
    try {
        const parsed = JSON.parse(rawJson) as Partial<PersistedLibraryIndexSnapshot>;
        if (
            !parsed
            || parsed.version !== LIBRARY_INDEX_SCHEMA_VERSION
            || !Array.isArray(parsed.songs)
        ) {
            return null;
        }
        const snapshot: PersistedLibraryIndexSnapshot = {
            version: LIBRARY_INDEX_SCHEMA_VERSION,
            updatedAt: Number(parsed.updatedAt) || Date.now(),
            songs: parsed.songs,
            entities: Array.isArray(parsed.entities) ? parsed.entities : undefined,
            assignments: Array.isArray(parsed.assignments) ? parsed.assignments : undefined,
        };
        memoryLibraryIndex = snapshot;
        return snapshot;
    } catch {
        return null;
    }
};

export const writePersistedLibraryIndex = async (payload: {
    songs: LocalSong[];
    entities?: LocalLibraryEntity[];
    assignments?: LocalLibraryAssignment[];
}): Promise<void> => {
    const snapshot: PersistedLibraryIndexSnapshot = {
        version: LIBRARY_INDEX_SCHEMA_VERSION,
        updatedAt: Date.now(),
        songs: payload.songs,
        entities: payload.entities ?? memoryLibraryIndex?.entities,
        assignments: payload.assignments ?? memoryLibraryIndex?.assignments,
    };
    memoryLibraryIndex = snapshot;
    try {
        await writeAndroidDiskCacheJson('index', LIBRARY_INDEX_CACHE_KEY, JSON.stringify(snapshot));
    } catch {
        // Ignore disk write failure.
    }
};

export const updatePersistedLibraryIndexSongs = async (upsertedSongs: LocalSong[]): Promise<void> => {
    if (upsertedSongs.length === 0) return;
    const current = await readPersistedLibraryIndex();
    const byId = new Map<string, LocalSong>(
        (current?.songs ?? []).map(song => [song.id, song]),
    );
    for (const song of upsertedSongs) {
        const existing = byId.get(song.id);
        if (existing && song.matchedLyrics === undefined && !song.markedPureMusic && existing.matchedLyrics) {
            byId.set(song.id, {
                ...song,
                matchedLyrics: existing.matchedLyrics,
                matchedLyricsSongId: song.matchedLyricsSongId ?? existing.matchedLyricsSongId,
                matchedLyricsSource: song.matchedLyricsSource ?? existing.matchedLyricsSource,
                matchedLyricsProviderPlatform: song.matchedLyricsProviderPlatform ?? existing.matchedLyricsProviderPlatform,
                matchedIsPureMusic: song.matchedIsPureMusic ?? existing.matchedIsPureMusic,
                matchedLyricsFetchedAt: song.matchedLyricsFetchedAt ?? existing.matchedLyricsFetchedAt,
                matchedLyricsQuerySignature: song.matchedLyricsQuerySignature ?? existing.matchedLyricsQuerySignature,
                onlineMetadata: song.onlineMetadata ?? existing.onlineMetadata,
                useOnlineCover: song.useOnlineCover ?? existing.useOnlineCover,
                lyricsSource: song.lyricsSource ?? existing.lyricsSource,
                hasManualLyricSelection: song.hasManualLyricSelection || existing.hasManualLyricSelection,
            });
        } else {
            byId.set(song.id, song);
        }
    }
    await writePersistedLibraryIndex({
        songs: Array.from(byId.values()),
        entities: current?.entities,
        assignments: current?.assignments,
    });
};

export const removePersistedLibraryIndexSongs = async (songIds: string[]): Promise<void> => {
    if (songIds.length === 0) return;
    const current = await readPersistedLibraryIndex();
    if (!current) return;
    const removeSet = new Set(songIds);
    const remaining = current.songs.filter(song => !removeSet.has(song.id));
    await writePersistedLibraryIndex({
        songs: remaining,
        entities: current.entities,
        assignments: current.assignments?.filter(a => !removeSet.has(a.songId)),
    });
};

export const clearPersistentDiskCacheNamespace = async (namespace: FoliaDiskCacheNamespace): Promise<void> => {
    if (namespace === 'lyrics') {
        memoryLyricsCache.clear();
        contentDigestToCacheKey.clear();
    } else if (namespace === 'palettes' || namespace === 'covers') {
        memoryPaletteCache.clear();
    } else if (namespace === 'index') {
        memoryLibraryIndex = null;
    }
    await deleteAndroidDiskCacheEntry(namespace, '*');
};

export const clearPersistentDiskCacheForTests = (): void => {
    memoryLyricsCache.clear();
    memoryPaletteCache.clear();
    contentDigestToCacheKey.clear();
    memoryLibraryIndex = null;
};

