        effects: withEffects({}),
    },
    pop: {
        gains: [-1, 1, 3, 4, 3, 0, -1, 1, 2, 3],
        effects: withEffects({}),
    },
    classical: {
        gains: [4, 3, 2, 1, -1, -1, 0, 2, 3, 4],
        effects: withEffects({}),
    },
    jazz: {
        gains: [3, 2, 1, 2, -1, -1, 0, 1, 3, 4],
        effects: withEffects({}),
    },
    bass: {
        gains: [6, 5, 3, 1, 0, -1, -1, 0, 1, 2],
        effects: withEffects({
            drive: 0.1,
            width: 1.15,
            punch: 0.45,
        }),
    },
    vocal: {
        gains: [-2, -1, 0, 2, 4, 4, 3, 1, 0, -1],
        effects: withEffects({
            highpass: 110,
