import { extractRepresentativeColorsFromPixels } from './colorPalette';
import { extractAssetIdFromCoverUrl, resolveLocalCoverObjectUrl } from '../services/localCoverRuntime';
import { buildBuiltinDualTheme } from '../hooks/themeControllerState';
import {
    readCachedCoverPalette,
    writeCachedCoverPalette,
} from '../services/persistentDiskCacheService';

// src/utils/colorExtractor.ts

interface RGB {
    r: number;
    g: number;
    b: number;
}

/**
 * 把图片缩到 50×50 读出像素（crossOrigin 匿名请求）。图片加载失败、没有 CORS 头、画布被污染（读像素抛
 * SecurityError）时都返回 null。silent：失败时不打 warn（墙上一批头像取色时用，失败只是回退）。
 */
export const loadImagePixels = async (imageUrl: string, { silent = false }: { silent?: boolean } = {}): Promise<Uint8ClampedArray | null> => {
    const resolvedUrl = extractAssetIdFromCoverUrl(imageUrl)
        ? (await resolveLocalCoverObjectUrl(imageUrl)) || imageUrl
        : imageUrl;

    return new Promise(resolve => {
        const img = new Image();
        img.crossOrigin = "Anonymous";

        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                resolve(null);
                return;
            }

            // Resize for performance
            const width = 50;
            const height = 50;
            canvas.width = width;
            canvas.height = height;

            try {
                ctx.drawImage(img, 0, 0, width, height);
                resolve(ctx.getImageData(0, 0, width, height).data);
            } catch (error) {
                // 画布被跨源图片污染时 getImageData 抛错；不吞掉的话这个 Promise 永远不 resolve。
                if (!silent) console.warn("Failed to read image pixels for color extraction", error);
                resolve(null);
            }
        };

        img.onerror = (e) => {
            if (!silent) console.warn("Failed to load image for color extraction", e);
            resolve(null);
        };
        img.src = resolvedUrl;
    });
};

const extractVibrantColorsFromPixels = (imageData: Uint8ClampedArray, count: number): string[] => {
    const colors: RGB[] = [];

    // Improved sampling: step = 2 instead of 5 for better coverage
    const step = 2;
    for (let i = 0; i < imageData.length; i += 4 * step) {
        const r = imageData[i];
        const g = imageData[i + 1];
        const b = imageData[i + 2];
        const a = imageData[i + 3];

        if (a < 128) continue; // Skip transparent

        // Calculate saturation and brightness
        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const l = (max + min) / 2;
        const saturation = max === min ? 0 : (max - min) / (255 - Math.abs(max + min - 255));

        // Prefer colors with some saturation (avoid pure grays)
        // and exclude very dark or very bright colors
        if (saturation > 0.2 && l > 30 && l < 220) {
            colors.push({ r, g, b });
        } else if (colors.length < 100) {
            // Still collect some low-saturation colors as fallback
            colors.push({ r, g, b });
        }
    }

    // Sort by saturation (vibrant colors first)
    colors.sort((a, b) => {
        const satA = (Math.max(a.r, a.g, a.b) - Math.min(a.r, a.g, a.b)) / 255;
        const satB = (Math.max(b.r, b.g, b.b) - Math.min(b.r, b.g, b.b)) / 255;
        return satB - satA;
    });

    // Extract distinct colors with lower distance threshold
    const distinctColors: RGB[] = [];
    const minDistance = 20; // Reduced from 30 for more variety

    for (const c of colors) {
        if (distinctColors.length >= count) break;

        const isDistinct = distinctColors.every(dc => {
            const d = Math.sqrt(
                Math.pow(c.r - dc.r, 2)
                + Math.pow(c.g - dc.g, 2)
                + Math.pow(c.b - dc.b, 2)
            );
            return d > minDistance;
        });

        if (isDistinct || distinctColors.length === 0) {
            distinctColors.push(c);
        }
    }

    return distinctColors.map(c => {
        const hexR = c.r.toString(16).padStart(2, '0');
        const hexG = c.g.toString(16).padStart(2, '0');
        const hexB = c.b.toString(16).padStart(2, '0');
        return `#${hexR}${hexG}${hexB}`;
    });
};

export const extractColors = async (imageUrl: string, count: number = 5): Promise<string[]> => {
    const cached = await readCachedCoverPalette(imageUrl);
    if (cached?.vibrantColors && cached.vibrantColors.length > 0) {
        return cached.vibrantColors.slice(0, count);
    }

    const pixels = await loadImagePixels(imageUrl);
    if (!pixels) return [];
    const targetCount = Math.max(count, 6);
    const vibrant = extractVibrantColorsFromPixels(pixels, targetCount);
    const representative = extractRepresentativeColorsFromPixels(pixels, targetCount);
    if (vibrant.length > 0 || representative.length > 0) {
        void writeCachedCoverPalette(imageUrl, {
            vibrantColors: vibrant,
            representativeColors: representative,
            dualTheme: vibrant.length > 0 ? buildBuiltinDualTheme({ coverColors: vibrant }) : undefined,
        });
    }
    return vibrant.slice(0, count);
};

export const extractRepresentativeColors = async (
    imageUrl: string,
    count: number = 5,
): Promise<string[]> => {
    const cached = await readCachedCoverPalette(imageUrl);
    if (cached?.representativeColors && cached.representativeColors.length > 0) {
        return cached.representativeColors.slice(0, count);
    }

    const pixels = await loadImagePixels(imageUrl);
    if (!pixels) return [];
    const targetCount = Math.max(count, 6);
    const representative = extractRepresentativeColorsFromPixels(pixels, targetCount);
    const vibrant = extractVibrantColorsFromPixels(pixels, targetCount);
    if (vibrant.length > 0 || representative.length > 0) {
        void writeCachedCoverPalette(imageUrl, {
            vibrantColors: vibrant,
            representativeColors: representative,
            dualTheme: vibrant.length > 0 ? buildBuiltinDualTheme({ coverColors: vibrant }) : undefined,
        });
    }
    return representative.slice(0, count);
};

