import type { ActiveLocalLyricsSource, LocalLyricsPriority, LocalSong, LyricData } from '../../types';
import { LyricParserFactory } from './LyricParserFactory';
import { hasKnownGoodWordByWordLocalLyric, hasTimedLocalOrEmbeddedLyric } from './lyricAutoMatchState';
import {
    clearPersistentDiskCacheForTests,
    computeParsedLyricsContentDigest,
    isPreSegmentedLyricsReady,
    readOfflineSavedLyricsForSong,
    readPreParsedLyricsFromDisk,
    writeOfflineSavedLyricsForSong,
    writePreParsedLyricsToDisk,
} from '../../services/persistentDiskCacheService';

// src/utils/lyrics/localSongLyrics.ts
// Resolves the lyric payload and its actual source from one local-song snapshot, caching parsed
// and pre-segmented TTML/LRC/VTT/QRC timing trees in memory and on persistent internal disk
// (context.getFilesDir()/media_cache/lyrics/) so track switches and offline playback load
// ready-to-render lyrics with zero XML/TTML parsing or network requirement.

export type ResolvedLocalSongLyrics = {
    lyrics: LyricData | null;
    source: ActiveLocalLyricsSource | null;
};

const MAX_PARSED_LYRIC_CACHE_ENTRIES = 200;
const parsedLocalLyricCache = new Map<string, LyricData | null>();

const buildLyricCacheKey = (
    song: LocalSong,
    source: 'local' | 'embedded',
    mainContent: string,
    transContent?: string,
    formatHint?: string,
): string => {
    const head = mainContent.slice(0, 48);
    const tail = mainContent.slice(-48);
    const transLen = transContent ? transContent.length : 0;
    const transTail = transContent ? transContent.slice(-32) : '';
    return `${song.id}::${source}::${formatHint || ''}::${song.fileSignature || ''}::${mainContent.length}::${head}::${tail}::${transLen}::${transTail}`;
};

const readCachedParsedLyrics = (key: string): LyricData | null | undefined => {
    if (!parsedLocalLyricCache.has(key)) return undefined;
    const value = parsedLocalLyricCache.get(key) ?? null;
    parsedLocalLyricCache.delete(key);
    parsedLocalLyricCache.set(key, value);
    return value;
};

const writeCachedParsedLyrics = (key: string, value: LyricData | null): void => {
    parsedLocalLyricCache.delete(key);
    parsedLocalLyricCache.set(key, value);
    while (parsedLocalLyricCache.size > MAX_PARSED_LYRIC_CACHE_ENTRIES) {
        const oldestKey = parsedLocalLyricCache.keys().next().value;
        if (!oldestKey) break;
        parsedLocalLyricCache.delete(oldestKey);
    }
};

export const clearParsedLocalLyricCache = (): void => {
    parsedLocalLyricCache.clear();
    clearPersistentDiskCacheForTests();
};

export const selectLocalSongLyricsSource = (
    song: LocalSong,
    priority: LocalLyricsPriority,
): ActiveLocalLyricsSource | null => {
    if (song.lyricsSource) {
        if (song.lyricsSource === 'online' && (song.matchedLyrics || song.matchedIsPureMusic)) return 'online';
        if (song.lyricsSource === 'local' && song.localLyricsContent) return 'local';
        if (song.lyricsSource === 'embedded' && song.embeddedLyricsContent) return 'embedded';
        return null;
    }

    // 用户标记的纯音乐：没有显式选本地 / 内嵌时一律按纯音乐（空歌词），「不使用在线数据」等把来源清回自动也不例外。
    if (song.markedPureMusic) return 'online';

    const hasLocal = Boolean(song.hasLocalLyrics && song.localLyricsContent);
    const hasEmbedded = Boolean(song.hasEmbeddedLyrics && song.embeddedLyricsContent);
    const hasWordByWordLocalOrEmbedded = hasKnownGoodWordByWordLocalLyric(song);

    // 1. Always prefer local or embedded TTML / word-by-word lyrics first.
    if (hasWordByWordLocalOrEmbedded) {
        if (hasLocal) return 'local';
        if (hasEmbedded) return 'embedded';
    }

    // 2. When the song has local or embedded non-TTML lyrics:
    //    - Upgrade to online matchedLyrics whenever online matchedLyrics is TTML / word-by-word,
    //      or when embedded/local text is untimed plain text, or when priority === 'online'.
    if (hasLocal || hasEmbedded) {
        const hasTimedLocalOrEmbedded = hasTimedLocalOrEmbeddedLyric(song);
        const onlineIsBetterTtmlOrWord = Boolean(
            song.matchedLyrics
            && (song.matchedLyrics.isWordByWord || song.matchedLyrics.ttml)
        );
        if (
            onlineIsBetterTtmlOrWord
            || (!hasTimedLocalOrEmbedded && Boolean(song.matchedLyrics))
            || (priority === 'online' && Boolean(song.matchedLyrics))
        ) {
            return 'online';
        }
        if (hasLocal) return 'local';
        if (hasEmbedded) return 'embedded';
    }

    if (song.matchedLyrics) return 'online';
    return null;
};

/** Parses the payload selected by the explicit source or current automatic priority, recovering offline-saved online lyrics if needed. */
export const resolveLocalSongLyrics = async (
    song: LocalSong,
    priority: LocalLyricsPriority,
): Promise<ResolvedLocalSongLyrics> => {
    if (!song.matchedLyrics && !song.markedPureMusic && !song.matchedIsPureMusic) {
        const recoveredOffline = await readOfflineSavedLyricsForSong(song.id, song.fileSignature);
        if (recoveredOffline) {
            song.matchedLyrics = recoveredOffline;
        }
    }

    const source = selectLocalSongLyricsSource(song, priority);
    if (source === 'online') {
        const matched = song.matchedLyrics ?? null;
        if (matched) {
            void writeOfflineSavedLyricsForSong(song.id, song.fileSignature, matched);
            const digest = computeParsedLyricsContentDigest(matched);
            if (digest) {
                const diskCached = await readPreParsedLyricsFromDisk(`matched_${digest}`);
                if (diskCached) {
                    return { lyrics: diskCached, source };
                }
                void writePreParsedLyricsToDisk(`matched_${digest}`, matched);
            }
        }
        return { lyrics: matched, source };
    }
    if (source === 'local') {
        const cacheKey = buildLyricCacheKey(
            song,
            'local',
            song.localLyricsContent!,
            song.localTranslationLyricsContent,
            song.localLyricsFormat,
        );
        const cached = readCachedParsedLyrics(cacheKey);
        if (cached !== undefined && isPreSegmentedLyricsReady(cached)) {
            return { lyrics: cached, source };
        }
        const lyrics = await LyricParserFactory.parse({
            type: 'local',
            lrcContent: song.localLyricsContent!,
            tLrcContent: song.localTranslationLyricsContent,
            formatHint: song.localLyricsFormat,
        });
        writeCachedParsedLyrics(cacheKey, lyrics);
        return { lyrics, source };
    }
    if (source === 'embedded') {
        const cacheKey = buildLyricCacheKey(
            song,
            'embedded',
            song.embeddedLyricsContent!,
            song.embeddedTranslationLyricsContent,
        );
        const cached = readCachedParsedLyrics(cacheKey);
        if (cached !== undefined && isPreSegmentedLyricsReady(cached)) {
            return { lyrics: cached, source };
        }
        const lyrics = await LyricParserFactory.parse({
            type: 'embedded',
            textContent: song.embeddedLyricsContent!,
            translationContent: song.embeddedTranslationLyricsContent,
        });
        writeCachedParsedLyrics(cacheKey, lyrics);
        return { lyrics, source };
    }
    return { lyrics: null, source: null };
};

src/utils/lyrics/lyricAutoMatchState.ts:
import type { LocalSong } from '../../types';
import { getFromCache, saveToCache } from '../../services/db';

// src/utils/lyrics/lyricAutoMatchState.ts
// Tracks persistent and in-memory automatic lyric lookup state, retrieval metadata,
// and negative-lookup cooldowns so unavailable tracks are not repeatedly queried on every play.

export const LOCAL_LYRIC_NEGATIVE_CACHE_KEY = 'local_lyric_negative_cache_v1';
export const AUTO_MATCH_FAILURE_COOLDOWN_MS = 24 * 60 * 60 * 1000; // 24 hours
const MAX_NEGATIVE_CACHE_ENTRIES = 2000;

export interface NegativeLyricMatchRecord {
    songId: string;
    signature: string;
    failedAt: number;
}

const memoryNegativeCache = new Map<string, NegativeLyricMatchRecord>();
let negativeCacheHydrated = false;
let negativeCacheHydrationPromise: Promise<void> | null = null;

export const normalizeLookupToken = (value?: string | null): string => (
    (value || '')
        .normalize('NFKC')
        .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
        .replace(/[أإآ]/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي')
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim()
);

export const buildSongLyricLookupSignature = (song: LocalSong): string => {
    const title = normalizeLookupToken(song.title || song.fileName);
    const artists = (
        song.onlineMetadata?.artists?.map(a => a.name).join(',')
        || song.importedMetadata?.artistNames?.join(',')
        || ''
    );
    const album = (
        song.onlineMetadata?.album?.name
        || song.importedMetadata?.albumName
        || ''
    );
    const durationBucket = Math.round((song.duration || 0) / 1000);
    const candidateKey = song.onlineMetadata?.source && song.onlineMetadata?.songId !== undefined
        ? `${song.onlineMetadata.source}:${song.onlineMetadata.songId}`
        : '';
    return `${title}|${normalizeLookupToken(artists)}|${normalizeLookupToken(album)}|${durationBucket}|${candidateKey}`;
};

export const hydrateNegativeLyricMatchCache = async (): Promise<void> => {
    if (negativeCacheHydrated) return;
    if (negativeCacheHydrationPromise) {
        await negativeCacheHydrationPromise;
        return;
    }
    negativeCacheHydrationPromise = (async () => {
        try {
            const stored = await getFromCache<Record<string, NegativeLyricMatchRecord>>(LOCAL_LYRIC_NEGATIVE_CACHE_KEY);
            if (stored && typeof stored === 'object') {
                for (const [songId, entry] of Object.entries(stored)) {
                    if (entry && typeof entry.failedAt === 'number' && typeof entry.signature === 'string') {
                        memoryNegativeCache.set(songId, entry);
                    }
                }
            }
        } catch {
            // Ignore cache read failures in restricted environments
        } finally {
            negativeCacheHydrated = true;
            negativeCacheHydrationPromise = null;
        }
    })();
    await negativeCacheHydrationPromise;
};

const persistNegativeCacheSnapshot = async (): Promise<void> => {
    try {
        const serialized: Record<string, NegativeLyricMatchRecord> = {};
        for (const [songId, record] of memoryNegativeCache.entries()) {
            serialized[songId] = record;
        }
        await saveToCache(LOCAL_LYRIC_NEGATIVE_CACHE_KEY, serialized);
    } catch {
        // Ignore persistence errors
    }
};

export const recordAutomaticLyricMatchFailure = async (
    song: LocalSong,
    now = Date.now(),
): Promise<void> => {
    const signature = buildSongLyricLookupSignature(song);
    song.lastAutoMatchFailedAt = now;
    song.lastAutoMatchFailedQuerySignature = signature;

    memoryNegativeCache.delete(song.id);
    memoryNegativeCache.set(song.id, {
        songId: song.id,
        signature,
        failedAt: now,
    });
    if (memoryNegativeCache.size > MAX_NEGATIVE_CACHE_ENTRIES) {
        const oldestKey = memoryNegativeCache.keys().next().value;
        if (oldestKey !== undefined) {
            memoryNegativeCache.delete(oldestKey);
        }
    }
    await persistNegativeCacheSnapshot();
};

export const recordAutomaticLyricMatchSuccess = async (
    song: LocalSong,
    now = Date.now(),
): Promise<void> => {
    const signature = buildSongLyricLookupSignature(song);
    song.matchedLyricsFetchedAt = now;
    song.matchedLyricsQuerySignature = signature;
    song.lastAutoMatchFailedAt = undefined;
    song.lastAutoMatchFailedQuerySignature = undefined;
    if (memoryNegativeCache.delete(song.id)) {
        await persistNegativeCacheSnapshot();
    }
};

export const clearNegativeLyricMatchRecord = async (songId?: string): Promise<void> => {
    if (!songId) {
        memoryNegativeCache.clear();
        negativeCacheHydrated = false;
        await persistNegativeCacheSnapshot();
        return;
    }
    if (memoryNegativeCache.delete(songId)) {
        await persistNegativeCacheSnapshot();
    }
};

export const isSongOnAutomaticLyricMatchCooldown = (
    song: LocalSong,
    now = Date.now(),
): boolean => {
    const currentSignature = buildSongLyricLookupSignature(song);
    if (
        typeof song.lastAutoMatchFailedAt === 'number'
        && song.lastAutoMatchFailedQuerySignature === currentSignature
        && (now - song.lastAutoMatchFailedAt) < AUTO_MATCH_FAILURE_COOLDOWN_MS
    ) {
        return true;
    }
    const cached = memoryNegativeCache.get(song.id);
    if (
        cached
        && cached.signature === currentSignature
        && (now - cached.failedAt) < AUTO_MATCH_FAILURE_COOLDOWN_MS
    ) {
        return true;
    }
    return false;
};

export const hasKnownGoodWordByWordLocalLyric = (song: LocalSong): boolean => {
    if (song.hasLocalLyrics && song.localLyricsContent) {
        const fmt = song.localLyricsFormat;
        if (fmt === 'ttml' || fmt === 'qrc' || fmt === 'yrc' || fmt === 'krc') {
            return true;
        }
        if (/<tt(?:\s|>)/i.test(song.localLyricsContent) || /<\d{1,2}:\d{2}/.test(song.localLyricsContent)) {
            return true;
        }
    }
    if (song.hasEmbeddedLyrics && song.embeddedLyricsContent) {
        if (/<tt(?:\s|>)/i.test(song.embeddedLyricsContent) || /<\d{1,2}:\d{2}/.test(song.embeddedLyricsContent)) {
            return true;
        }
    }
    return false;
};

export const hasTimedLocalOrEmbeddedLyric = (song: LocalSong): boolean => {
    if (hasKnownGoodWordByWordLocalLyric(song)) return true;
    const isTimedText = (text?: string | null): boolean => {
        if (!text) return false;
        return /\[\d{1,3}:\d{2}(?:[.:]\d{1,3})?\]/.test(text)
            || /\d{2}:\d{2}:\d{2}[.,]\d{3}\s*-->/.test(text)
            || /<\s*p\b[^>]*\bbegin\s*=/i.test(text);
    };
    return (Boolean(song.hasLocalLyrics) && isTimedText(song.localLyricsContent))
        || (Boolean(song.hasEmbeddedLyrics) && isTimedText(song.embeddedLyricsContent));
};

