            const line0 = lyricsNodes.find(n => n.props?.['data-lyric-index'] === 0);
            const line1 = lyricsNodes.find(n => n.props?.['data-lyric-index'] === 1);
            const line25 = lyricsNodes.find(n => n.props?.['data-lyric-index'] === 25);

