        expect(paletteCalls).toEqual([{ colors: paletteColors, transitionMs: 900 }]);

        // 4. Pushing audio energy clamps normalized bands [0..1]
        const energyOk = await setAndroidNativeVisualizerEnergy({
            bass: 0.82,
            mid: 0.54,
